  const r=MOBILE_RENDER;if(!mobileRenderEnabled()||!terrain||typeof drawScenery!=='function')return 0;
  const bakeKinds=new Set(['grass','flowers','bush']),tc=terrain.getContext('2d');if(!tc)return 0;
