// ---- beta/02a-story-content.js ----
'use strict';
// Textos da campanha. IDs persistidos aqui também são a whitelist do Save V7.
const STORY_DEFS={
 chapters:{arrival:'A maré fora do compasso',seals:'Os três reguladores',marks:'Cinco costas',mechanisms:'A rede do Navegador',final:'A última maré'},
 scenes:{
  'story.arrival.mara':{priority:70,title:'A maré fora do compasso',nodes:[['Mara','A maré trouxe problemas. Você trouxe um pombo.'],['', 'Pipoca pousa no balcão e bica uma colher.'],['Mara','Não vou perguntar qual dos dois é pior.'],['Mara','A corrente parou de obedecer. Três bichos estão segurando três selos.'],['Mara','Musgo. Lodo. Bronze.'],['Mara','Traga os três e o caminho do Recife abre.'],['Mara','Depois você conversa com o sujeito que resolveu ser dono do mar.'],['','Pipoca rouba um botão que não parece servir para nada.'],['Mara','E tire esse pombo das minhas coisas.']],entry:{id:'journal.arrival',title:'A maré fora do compasso',text:'A corrente em torno da ilha deixou de seguir seu ciclo. Mara diz que três guardiões carregam selos ligados ao Recife. Não há uma ordem certa para procurá-los. Enquanto a maré permanecer presa, nenhuma rota de saída é confiável.'}},
  'story.region.fields':{priority:20,title:'Campos do Vento',nodes:[['Nilo','O vento muda antes do tempo. As casas aprenderam a viver com isso melhor do que as pessoas.']],entry:{id:'journal.region.meadow',title:'Campos do Vento',text:'O vento aqui muda antes do tempo. As casas aprenderam a viver com isso melhor do que as pessoas.'}},
  'story.region.forest':{priority:20,title:'Bosque Sussurrante',nodes:[['Nilo','Raízes novas sobre caminhos muito antigos.'],['','Pipoca inclina a cabeça para uma direção e segue bicando o chão.']],entry:{id:'journal.region.forest',title:'Bosque Sussurrante',text:'Raízes novas cobrem caminhos muito antigos. Pipoca parece interessado em algo adiante, embora também pareça interessado em qualquer coisa que possa bicar.'}},
  'story.region.swamp':{priority:20,title:'Brejo Brilhante',nodes:[['Nilo','A água parece parada. O chão, não.']],entry:{id:'journal.region.marsh',title:'Brejo Brilhante',text:'A água parece parada. O chão, não.'}},
  'story.region.dunes':{priority:20,title:'Dunas Douradas',nodes:[['Nilo','Ferrugem no deserto. Isso já esteve mais perto do mar.']],entry:{id:'journal.region.dunes',title:'Dunas Douradas',text:'Ferrugem no deserto. Isso já esteve mais perto do mar.'}},
  'story.region.reef':{priority:20,title:'Recife Esquecido',nodes:[['Nilo','O mar daqui não parece baixo. Parece contido.']],entry:{id:'journal.region.reef',title:'Recife Esquecido',text:'O mar daqui não parece baixo. Parece contido.'}},
  'story.weather.storm':{priority:10,toastOnly:true,nodes:[['Damião','Agora ela está tentando respirar com alguém sentado no peito.']]},
  'story.weather.fogReef':{priority:10,toastOnly:true,nodes:[['Nilo','A costa some antes de mudar.']]},
  'story.weather.lowTideMark':{priority:10,toastOnly:true,nodes:[['Nena','É sempre quando a água recua que o passado aparece.']]},
  'story.seal.moss':{priority:80,title:'Selo de Musgo',nodes:[['','Uma vibração percorre as raízes. Pipoca pousa perto de um trecho recém-exposto.'],['Nilo','A raiz soltou o caminho em vez de apertá-lo.']],entry:{id:'journal.seal.moss',title:'Selo de Musgo',text:'As raízes do Bosque pareciam invasoras, mas parte delas seguia linhas antigas do terreno. Quando o selo foi removido, algumas recuaram e outras se firmaram. Talvez estivessem tentando segurar lembranças de uma costa que já não existe.\n\nA ilha cria raízes para lembrar onde esteve.'}},
  'story.seal.mud':{priority:80,title:'Selo de Lodo',nodes:[['Nilo','A água começou a procurar saída.'],['','Pipoca evita o lodo, depois bica algo que surgiu com a água.']],entry:{id:'journal.seal.mire',title:'Selo de Lodo',text:'O Brejo acumulou água e sedimento por tempo demais. Estruturas sob a lama parecem pertencer a outra margem, talvez de uma época em que a costa atravessava esta região. O movimento não destruiu esse lugar. A falta dele quase conseguiu.\n\nO chão que afunda ainda está procurando outra forma.'}},
  'story.seal.bronze':{priority:80,title:'Selo de Bronze',nodes:[['Nilo','Não era uma âncora.'],['','Um mecanismo próximo responde. Pipoca pousa sobre uma peça que ainda se move.']],entry:{id:'journal.seal.bronze',title:'Selo de Bronze',text:'As estruturas das Dunas parecem feitas para suportar tensão distribuindo-a entre várias partes. Não foram construídas para manter tudo imóvel. Foram construídas para permitir movimento sem ruptura.\n\nO metal não prendia a ilha. Distribuía sua força.'}},
  'story.progress.firstSeal':{priority:70,title:'A ilha responde',nodes:[['Mara','Um já mexeu com a ilha.'],['Nilo','Isso é bom ou ruim?'],['Mara','Quando eu souber, você vai ser o segundo.']]},
  'story.progress.twoSeals':{priority:70,title:'A maré irritada',nodes:[['Mara','Antes, o mar estava errado. Agora ele está irritado.'],['Nena','Comparei meus mapas de novo. Talvez o problema não seja eles discordarem. Talvez todos estejam certos.'],['Damião','Mar preso não fica quieto. Só fica juntando vontade.'],['Ivo','Estrutura velha estala antes de ceder. O Recife está estalando.']]},
  'story.esponjao.firstVoice':{priority:50,title:'Voz distante',nodes:[['Esponjão','Continuem.'],['Esponjão','Facilitam muito o meu trabalho.'],['','Pipoca olha para o lado errado e continua procurando migalhas.']]},
  'story.marks.complete':{priority:30,title:'Cinco costas',nodes:[['Nena','Cinco mapas.'],['Nena','Cinco ilhas.'],['Nena','Não. A mesma ilha.'],['Nena','Olha isso. Existe uma sexta forma por baixo de todas. E o centro quase não muda.'],['Nena','Não é um mapa para chegar a algum lugar. É um mapa para provar que o lugar chegou até nós.']],entry:{id:'journal.marks',title:'Cinco costas',text:'As cinco marcas registram versões diferentes da mesma ilha. Quando os mapas são sobrepostos, surge uma sexta forma, centrada no Abrigo de Mara. Nena acredita que algumas partes da ilha se deslocam enquanto outras quase permanecem.'}},
  'story.marks.third':{priority:30,title:'Marcas antigas',nodes:[['Nena','Um erro de mapa acontece. Três erros iguais começam a virar documento.']]},
  'story.mechanisms.first':{priority:30,title:'Mecanismo antigo',nodes:[['Nilo','Construção antiga. Ainda responde.']]},
  'story.mechanisms.second':{priority:30,title:'Mecanismos antigos',nodes:[['Ivo','Isso não foi feito para ficar travado.']]},
  'story.mechanisms.third':{priority:30,title:'Mecanismos antigos',nodes:[['Nilo','Há sinais de que os mecanismos faziam parte da mesma rede.']]},
  'story.mechanisms.fourth':{priority:30,title:'Mecanismos antigos',nodes:[['Ivo','Olha a folga. Quem fez isso queria movimento.']]},
  'story.marks.safePoint':{priority:30,title:'Ponto manso',nodes:[['Mara','Escolhi esse lugar porque o chão não encharcava. O vento também desviava. Achei que finalmente tinha aprendido alguma coisa.'],['Nena','Aprendeu. Só não sabia que estava medindo a ilha.'],['Nena','Ponto manso.'],['Mara','Nome horrível.']]},
  'story.mechanisms.complete':{priority:30,title:'A rede do Navegador',nodes:[['Ivo','Isso não foi feito para ficar travado.'],['Ivo','Olha a folga. Quem fez isso queria movimento.'],['Ivo','Agora entendi. Não seguravam a ilha. Dividiam a força quando ela mexia.']],entry:{id:'journal.mechanisms',title:'A rede do Navegador',text:'Eclusas, contrapesos, luzes e cordames fazem parte de um sistema maior. Os mecanismos não parecem destinados a impedir mudanças na ilha. Pelo contrário: foram feitos para permitir que ela cedesse, movesse água e redistribuísse tensão sem se destruir.'}},
  'story.progress.threeSeals':{priority:90,title:'Os três selos',nodes:[['','Os três selos respondem ao Recife. A água vibra e as ruínas devolvem um som grave. Pipoca fica atento à costa.'],['Esponjão','Vocês trouxeram meus selos de volta.'],['Esponjão','Que gentileza.']],entry:{id:'journal.lastTide',title:'A última maré',text:'Os selos abriram o caminho até o Recife, mas também fizeram os antigos sistemas reagirem ao mesmo tempo. Esponjão parecia esperar por isso. Recuperar os selos talvez tenha devolvido ao Recife algo além de uma passagem.'}},
  'story.mara.beforeFinal':{priority:70,title:'Antes da última maré',nodes:[['Mara','Então é isso. Três selos.'],['Mara','Um pombo ainda sem utilidade comprovada.'],['','Pipoca rouba algo da mesa.'],['Mara','Tá. Utilidade discutível.'],['Mara','Você vai ao Recife. Volta inteiro. O pombo pode voltar no estado habitual.']]},
  'story.reef.approach':{priority:70,title:'A costa contida',nodes:[['Nilo','Isso não parece uma costa destruída.'],['Nilo','Parece uma costa impedida de terminar de mudar.']]},
  'story.boss.intro':{priority:100,title:'Esponjão',nodes:[['Esponjão','Até que enfim. Olhem em volta. Tudo ainda está onde eu deixei.'],['Esponjão','Roubei? Eu guardei.'],['Esponjão','Maré solta muda caminho. Engole casa. Apaga nome.'],['Esponjão','Vi costas desaparecerem, estruturas afundarem. Concluí que movimento significa perda.'],['Esponjão','Absorvi água, resíduos e fragmentos do Recife. Às vezes acho que ainda guardo as costas antigas.'],['Esponjão','Se nada mudar, nada poderá ser perdido. Prendi a corrente principal e separei os três selos.'],['Esponjão','Meu reino fica onde eu mandei ficar.'],['Esponjão','E vocês trouxeram as chaves.']]},
  'story.boss.defeated':{priority:100,title:'Maré livre',nodes:[['Esponjão','Vai mudar tudo.'],['Esponjão','Era justamente esse o problema.'],['','Pipoca bica um pedaço inútil da arena.']]},
  'story.epilogue.basic':{priority:90,title:'Maré livre',nodes:[['Mara','O mar está se comportando. Quer dizer, do jeito dele.'],['Mara','As rotas abriram. Se quiser partir, pode.'],['','Pipoca derruba alguma coisa da mesa.'],['Mara','Depois que resolver isso.'],['Nilo','Depois.']],entry:{id:'journal.epilogue',title:'Maré livre',text:'As correntes voltaram a circular pelo Recife e antigas rotas começaram a se abrir. A ilha não retornou ao que era antes. Talvez esse nunca tenha sido o objetivo.'}},
  'story.epilogue.marks':{priority:40,title:'Um mapa novo',nodes:[['Nena','Tenho uma notícia ruim. Meu mapa já está errado. A costa mudou.'],['Nilo','Quanto?'],['Nena','Pouco. O bastante. Acho que vou precisar de mapas com datas.']]},
  'story.epilogue.mechanisms':{priority:40,title:'Uma rede em movimento',nodes:[['Ivo','Estão todos respondendo. Um puxa, outro cede, outro distribui. É uma rede.'],['Ivo','Quem montou isso sabia que coisa viva não fica parada.']]},
  'story.epilogue.community':{priority:40,title:'Um mapa compartilhado',nodes:[['','Nena desenha. Damião corrige com as correntes. Ivo indica os mecanismos. Mara pergunta por que todos ocuparam sua mesa. Pipoca pisa no mapa.'],['Mara','Ótimo. Primeiro mapa da ilha feito com erro oficial.'],['Nena','Não é erro.'],['Mara','Pior ainda.']]}
 },
 journalEntries:{'journal.mark1':{title:'Uma costa antiga',text:'Uma marca antiga não coincide com a costa atual.'},'journal.mark2':{title:'Duas costas',text:'Duas marcas apontam para linhas costeiras incompatíveis entre si.'},'journal.mark4':{title:'Ruínas longe do mar',text:'Há estruturas longe demais da água para que sua posição atual faça sentido.'},'journal.mechanism1':{title:'Construção antiga',text:'Construção antiga. Ainda responde.'},'journal.mechanism2':{title:'Folga calculada',text:'Ivo observou que o mecanismo não foi feito para ficar travado.'},'journal.mechanism3':{title:'Sinais de uma rede',text:'Os mecanismos mostram sinais de que faziam parte de uma mesma rede.'},'journal.mechanism4':{title:'Movimento previsto',text:'Ivo encontrou folga intencional nas peças. Quem as montou esperava que se movessem.'}},countertideIntros:{iron:{title:'A ilha lembra da força.',text:'Certos inimigos resistem como se já soubessem onde o golpe vai chegar.'},wake:{title:'A ilha lembra do impacto.',text:'Golpes antigos parecem deixar ecos onde antes havia apenas água.'},short:{title:'A ilha lembra do tempo.',text:'O ciclo se fecha mais depressa. O intervalo seguro ficou menor.'},route:{title:'A ilha lembra do caminho.',text:'Uma rota descoberta anteriormente permanece reconhecível, mesmo quando o resto parece recomeçar.'}},
 npcReactions:{nena:'Talvez todos os mapas estejam certos.',damiao:'Mar preso não fica quieto. Só fica juntando vontade.',ivo:'Estrutura velha estala antes de ceder. O Recife está estalando.'},
 environmentalBeats:{twoSeals:['A água devolve ecos de uma costa antiga.','O vento muda antes do tempo.','A ilha lembra.']}
};



