 c.save();c.clip(innerPath);
 c.beginPath();c.moveTo(0,0);c.lineTo(WORLD.w,0);c.lineTo(WORLD.w,1450);c.bezierCurveTo(4210,1330,3440,1760,2850,1570);c.bezierCurveTo(2360,1510,1950,1880,1410,1600);c.bezierCurveTo(1030,1510,720,1680,0,1470);c.closePath();c.fillStyle='#668b6d';c.fill();
