function gridAdd(s){if(!s.collision)return;const key=Math.floor(s.x/180)+','+Math.floor(s.y/180);if(!staticGrid.has(key))staticGrid.set(key,[]);staticGrid.get(key).push(s)}
function obstacles(x,y){let found=[],gx=Math.floor(x/180),gy=Math.floor(y/180);for(let a=gx-1;a<=gx+1;a++)for(let b=gy-1;b<=gy+1;b++){let list=staticGrid.get(a+','+b);if(list)found.push(...list)}return found}
function obstacleRadiusFor(s,actor=null){if(actor!==player)return s.r;const vegetation=['tree','pine','palm','willow','cactus','mushroom','coral'].includes(s.kind);return s.r*(vegetation?.58:.80)}
