function moveEntity(e,dx,dy,ignore=false){let nx=e.x+dx,ny=e.y+dy,r=e.r||12;if(ignore){if(terrainGroundAt(nx,ny,25)&&!v3SolidAt(nx,ny,r,e===player&&hook?.target?.id==='v3-reef-anchor'&&hook.mode==='reeling')){e.x=nx;e.y=ny}return}if(walkable(nx,e.y,r,e))e.x=nx;if(walkable(e.x,ny,r,e))e.y=ny}
