function drawPlayer(){if(playerRendererBridge?.ready){playerRendererBridge.drawBody(ctx,player.x,player.y);return;}const c=ctx;if(player.invuln>0&&Math.floor(G.time*18)%2)c.globalAlpha=.6;let bob=player.moving?Math.sin(player.walk*2)*1.1:Math.sin(G.time*2)*.4;circle(c,player.x,player.y+4,21,null,'#e9d59b44',1.5);drawHuman(player.x,player.y+bob,1.07,'player',player.angle,player.moving?player.walk:0);c.globalAlpha=1;if(player.charging&&player.chargeTime>.12){const q=clamp(player.chargeTime/.95,0,1),pulse=.5+.5*Math.sin(G.time*15);c.save();c.globalAlpha=.35+.4*q;circle(c,player.x,player.y-8,24+q*16+pulse*2,null,q>.7?'#ffe29a':'#d8c585',1.5+q*2);for(let i=0;i<3;i++){let a=G.time*(1.3+i*.17)+i*TAU/3;circle(c,player.x+Math.cos(a)*(24+q*10),player.y-8+Math.sin(a)*(15+q*7),1.5+q,'#f2d894')}c.restore()}if(player.parryFlash>0){const p=1-player.parryFlash/.42;c.save();c.globalAlpha=clamp(player.parryFlash/.42,0,1);c.beginPath();c.arc(player.x,player.y-8,25+p*15,player.angle-1.05,player.angle+1.05);c.strokeStyle='#fff0ae';c.lineWidth=4;c.stroke();c.restore()}else if(player.parryWindow>0){c.save();c.globalAlpha=.7;circle(c,player.x,player.y-8,24,null,'#f4dfa2',2);c.restore()}if(player.perfectFlash>0){const p=1-player.perfectFlash/.34;c.save();c.globalAlpha=clamp(player.perfectFlash/.34,0,1)*.9;circle(c,player.x,player.y-9,24+p*22,null,'#f7dea0',2.5);circle(c,player.x,player.y-9,15+p*12,null,'#fff1bb88',1.2);c.restore()}else if(player.perfectReady&&player.perfectWindow>0){c.save();c.globalAlpha=.45;circle(c,player.x,player.y-8,23,null,'#e9d594',1.2);c.restore()}}
function drawPigeon(){const c=ctx;c.save();c.translate(bird.x,bird.y-15);let flip=Math.cos(player.angle)<-.15?-1:1;c.scale(flip,1);let w=Math.sin(G.time*16)*.65,flap=bird.attackAnim>0?1.4:1;ellipse(c,0,48,10,3,'#3e634324');ellipse(c,-2,-1,10,7,'#ecebd9');c.save();c.translate(-2,-3);c.rotate(-.38-w*flap);ellipse(c,-6,-3,13,5,'#aebcb0',-.3);line(c,[[-15,-6],[-3,-4]],'#f1eee1',1);line(c,[[-13,-3],[-3,-2]],'#e1e4d5',1);c.restore();c.save();c.translate(-1,-1);c.rotate(.5+w*flap);ellipse(c,-4,4,9,4,'#d6ddcb');c.restore();ellipse(c,7,-5,5,6,'#c0cabe',-.3);ellipse(c,5,-1,3,3,'#809d88');c.beginPath();c.moveTo(10,-6);c.lineTo(16,-4);c.lineTo(10,-2);c.fillStyle='#d9ac70';c.fill();circle(c,9,-6,1.15,'#263e34');line(c,[[-10,0],[-18,4],[-13,6]],'#a5b6ac',3);line(c,[[1,6],[0,9],[3,9]],'#d3a375',1.2);line(c,[[6,5],[6,8],[9,8]],'#d3a375',1.2);c.restore();if(bird.scoutTarget||bird.hintTime>0)worldLabel(bird.x,bird.y-43,'?','#f3dfa6',13);else if(bird.opportunity>0)worldLabel(bird.x,bird.y-43,'✦','#ffe6a0',12);else if(bird.celebrate>0)worldLabel(bird.x,bird.y-43,'!','#f2d98e',12)}
function star(c,x,y,r,color){c.beginPath();for(let i=0;i<10;i++){let a=-Math.PI/2+i*Math.PI/5,rrr=i%2?r*.45:r;i?c.lineTo(x+Math.cos(a)*rrr,y+Math.sin(a)*rrr):c.moveTo(x+Math.cos(a)*rrr,y+Math.sin(a)*rrr)}c.closePath();c.fillStyle=color;c.fill()}
function worldLabel(x,y,label,color='#eddfb7',size=11){ctx.font=`${size}px 'Trebuchet MS', Arial`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.lineWidth=3;ctx.strokeStyle='#203f2fab';ctx.strokeText(label,x,y);ctx.fillStyle=color;ctx.fillText(label,x,y)}
function drawCombatTelegraph(e,c){if(!smartEnemy(e))return;if(e.aiState==='alert')worldLabel(e.x,e.y-e.r*2.15-31,'!','#f4d18d',15);else if(e.aiState==='investigate')worldLabel(e.x,e.y-e.r*2.15-31,'?','#d8d7af',13);if(e.strikePending){const p=1-clamp(e.windup/(e.windupMax||.45),0,1),kind=e.strikePending,parryable=!['mushroomSpore'].includes(kind),col=kind==='wispBlink'?'#b8d8cf':kind==='mushroomSpore'?'#cdb3d4':parryable?'#efbf80':'#df8b7a';circle(c,e.x,e.y,e.r+10+p*9,null,col,2.2);if(parryable){c.save();c.globalAlpha=.65;for(let i=0;i<3;i++){let a=i*TAU/3+G.time*1.8;circle(c,e.x+Math.cos(a)*(e.r+15),e.y+Math.sin(a)*(e.r+15),2.2,col)}c.restore()}if(kind==='bandit'||kind==='banditVolley'||kind==='wispBlink'||kind==='crabRush'){c.save();c.globalAlpha=.25+.35*p;line(c,[[e.x,e.y-10],[player.x,player.y-4]],col,1);c.restore()}if(kind==='mushroomSpore'){circle(c,e.strikeX,e.strikeY,86,'#b88dc51c','#cdb3d4',1.5)}if(PREFS.telegraphLabels==='full'&&dist(e,player)<280&&p>.32){const label=kind==='mushroomSpore'?'ÁREA':kind==='wispBlink'?'TELEPORTE':kind==='banditVolley'?'RAJADA':kind==='bandit'?'DISPARO':kind==='crabRush'?'INVESTIDA':kind==='slimeLeap'?'SALTO':kind==='crab'?'PINÇA':'ATAQUE';worldLabel(e.x,e.y-e.r*2.15-43,label,col,7)}}if(e.type==='crab'&&e.guard>0){c.save();c.globalAlpha=.7;const ga=e.guardAngle;c.beginPath();c.arc(e.x,e.y,e.r+15,ga-.88,ga+.88);c.strokeStyle='#e7d59d';c.lineWidth=4;c.stroke();c.restore()}if(e.vulnerable>0){c.save();c.globalAlpha=.75;circle(c,e.x,e.y,e.r+18,null,'#ffe2a0',2);c.restore()}if(isExecutable(e)){const pulse=.5+.5*Math.sin(G.time*8);c.save();c.globalAlpha=.55+.3*pulse;circle(c,e.x,e.y,e.r+16+pulse*3,null,'#f4cb75',2.2);c.restore();if(dist(e,player)<110)worldLabel(e.x,e.y-e.r*2.1-28,'EXECUTAR','#ffe2a0',9)}if(DEBUG.visible)worldLabel(e.x,e.y+e.r+17,(e.aiState||'idle').toUpperCase(),'#b8d7bb',8)}
