function v3State(){if(!G.exploration)G.exploration={known:[],solved:[]};return G.exploration}
function v3Solved(id){return v3State().solved.includes(id)}
function v3PuzzleQuietZone(p=player,radius=275){if(!p)return false;for(const [id,s] of V3_SITE_ENTRIES){if(v3Solved(id))continue;if(dist(p,s)<radius)return true;}return false}

function v3Own(o,k){return typeof k==='string'&&Object.prototype.hasOwnProperty.call(o,k)}
function v3CleanState(raw){const valid=a=>Array.isArray(a)?[...new Set(a.filter(id=>v3Own(V3_SITES,id)))]:[],solved=valid(raw?.solved),extra=typeof livingCleanExploration==='function'?livingCleanExploration(raw):{},storyBeats=typeof storyCleanState==='function'?storyCleanState(raw?.storyBeats):undefined;return {known:[...new Set([...valid(raw?.known),...solved])],solved,...extra,...(storyBeats?{storyBeats}:{})}}
function migrateV6toV7(d){d.exploration={known:[],solved:[]};d.version=7;return d}
function v3Object(id){return V3.objects.find(o=>o.id===id)}
function v3Touch(){return matchMedia('(pointer:coarse)').matches}
function v3Key(action){return v3Touch()?({hook:'GANCHO',bird:'PIPOCA',interact:'INTERAGIR',quests:'DI\u00c1RIO'}[action]||action):keyLabel(actionKey(action))}
function v3InRect(x,y,b,r=0){return x>b.x-r&&x<b.x+b.w+r&&y>b.y-r&&y<b.y+b.h+r}
function v3Inside(x,y,b,pad=0){return ((x-b.x)/(b.rx+pad))**2+((y-b.y)/(b.ry+pad))**2<1}
function v3InletOpen(){return v3Solved('tidalLock')||(V3.valve>0&&lowTideOpen())||G.bossDefeated}
function v3WallOpen(b){return b.site==='tidalLock'?v3InletOpen():b.site==='counterweight'?(v3Solved(b.site)||V3.plate>=.45):b.site?v3Solved(b.site):G.seals.includes(b.seal)}
function v3GapAt(b,x,y,r){const q=b.axis==='x'?x:y;return q>b.gap[0]+r&&q<b.gap[1]-r}
function v3SolidAt(x,y,r=12,allowAnchor=false){for(const b of V3_WALLS){if(!v3InRect(x,y,b,r))continue;if(allowAnchor&&b.id==='inlet')continue;if(v3WallOpen(b)&&v3GapAt(b,x,y,r))continue;return b}for(const b of V3_COVERS)if(v3InRect(x,y,b,r))return b;return null}
function v3ShotBlock(a,b,r=3){const n=Math.max(1,Math.ceil(dist(a,b)/9));for(let i=0;i<=n;i++){const x=lerp(a.x,b.x,i/n),y=lerp(a.y,b.y,i/n);for(const c of V3_COVERS)if(v3InRect(x,y,c,r))return true;for(const c of V3_WALLS)if(['roots','grate'].includes(c.type)&&v3InRect(x,y,c,r)&&!(v3WallOpen(c)&&v3GapAt(c,x,y,r)))return true}return false}
function v3SafeArena(p){return dist(p,HOME)<230||dist(p,BOSS_POS)<510||GUARDIANS.some(q=>dist(p,q)<310)||V3_MINI_ARENAS.some(q=>dist(p,q)<185)}
function v3WindData(){const w=weatherNow().id,a=.22+Math.sin(Math.floor(G.playTime/18)*.71)*.24;return {x:Math.cos(a),y:Math.sin(a),force:w==='storm'?31:w==='wind'?27:w==='rain'?14:8}}
function v3Sheltered(p){const w=v3WindData();return V3_COVERS.some(b=>{const dx=p.x-(b.x+b.w/2),dy=p.y-(b.y+b.h/2),along=dx*w.x+dy*w.y,cross=Math.abs(-dx*w.y+dy*w.x);return along>0&&along<125&&cross<Math.max(b.w,b.h)*.57+18})}
function v3Hidden(p){return !v3SafeArena(p)&&V3_BRUSH.some(b=>v3Inside(p.x,p.y,b,-8))}
function v3BogAt(p){if(v3SafeArena(p))return null;for(const b of V3_BOGS){if(b.drains&&G.seals.includes('mire'))continue;if(v3Inside(p.x,p.y,b)&&!V3_STONES.some(s=>s.bog===b.id&&dist(p,s)<s.r+2))return b}return null}
function v3Walk(dt,v,scale){const bog=v3BogAt(player),boots=equipped('wet_boots');let dx=v.x*198*scale*dt*(bog?(boots ? .9 : .73):1),dy=v.y*198*scale*dt*(bog?(boots ? .9 : .73):1);const z=zoneAt(player.x,player.y).id;if((z==='meadow'||z==='dunes')&&!v3SafeArena(player)&&!v3Sheltered(player)){const wind=v3WindData();dx+=wind.x*wind.force*dt;dy+=wind.y*wind.force*dt}moveEntity(player,dx,dy)}
function v3Projectile(p,dt){if(p.type==='poop'||p.owner?.boss||p.owner?.guardian||p.owner?.miniBossId||v3SafeArena(p))return;const z=zoneAt(p.x,p.y).id;if((z==='meadow'||z==='dunes')&&!v3Sheltered(p)){const w=v3WindData();p.vx=clamp(p.vx+w.x*w.force*.72*dt,-550,550);p.vy=clamp(p.vy+w.y*w.force*.72*dt,-550,550)}if(v3ShotBlock(p,{x:p.x+p.vx*dt,y:p.y+p.vy*dt},p.r||4)){p.dead=true;V3.metrics.coverBlocks++;burst(p.x,p.y,'#d7c292',5,46)}}
function v3Awareness(e,base){if(!e.boss&&!e.guardian&&!e.miniBossId&&player.combat<=0&&player.attackAnim<=0&&!player.charging&&v3Hidden(player))return Math.min(base,e.type==='wisp'?175:112);return base}
function v3Say(msg,duration=3.6){V3.message=msg;V3.messageUntil=G.playTime+duration;v3UpdateHUD()}
function v3Pulse(id,kind='hit',label='',duration=1.15){const o=v3Object(id);if(!o)return;V3.feedback={id:o.id,kind,label,until:G.playTime+duration};o.feedbackUntil=G.playTime+duration;o.feedbackKind=kind;o.feedbackLabel=label;V3.metrics.mechanismCues=(V3.metrics.mechanismCues||0)+1}
function v3ObjectCue(o,label,kind='hit',duration=1.25){if(!o)return;v3Pulse(o.id,kind,label,duration);text(o.x,o.y-58,label,kind==='ok'?'#e7e9a8':kind==='warn'?'#ffd39b':'#f2dfa6',10);burst(o.x,o.y-18,kind==='ok'?'#e5e99b':kind==='warn'?'#e7a878':'#e9d492',kind==='warn'?7:10,kind==='warn'?55:70)}
function v3HookLatched(o){if(!o||o.kind!=='rigging'||v3Solved(o.site))return;v3Discover(o.site);V3.metrics.hookLocks=(V3.metrics.hookLocks||0)+1;v3ObjectCue(o,'ALVO PRESO · PUXE NOVAMENTE','hit',1.45);v3Say(o.name+' preso pelo gancho. Puxe novamente para acionar.',2.4)}
function v3HookMissFeedback(){const site=v3NearestSite(325);if(!site||v3Solved(site.id))return false;const n=(V3.misses[site.id]||0)+1;V3.misses[site.id]=n;if(n<2)return false;V3.misses[site.id]=0;const o=v3ExpectedObject(site.id);if(o){V3.metrics.hookMissHints=(V3.metrics.hookMissHints||0)+1;v3Pulse(o.id,'hint','ALVO DO MECANISMO',1.8);v3Say('O gancho não prendeu. O mecanismo respondeu com um brilho no alvo útil.',2.8);return true}return false}
function v3TargetRelevant(o){if(!o||v3Solved(o.site))return false;if(o.site==='counterweight')return V3.plate>=.45?o.role==='lock':o.role==='weight';if(o.site==='birdsong')return V3.birdTask?o.role==='winch':V3.bell>0?o.role==='perch':o.role==='bell';if(o.site==='marshLights')return o.role==='lamp';if(o.site==='glassArray')return o.role==='mirror';if(o.site==='tidalLock')return player.x>4910?o.role==='chain':o.role==='valve';return false}
function v3PuzzleProgress(id){if(id==='counterweight')return V3.plate>=.45?'ETAPA 2/2 · TRAVA':'ETAPA 1/2 · LASTRO';if(id==='birdsong')return V3.birdTask?'ETAPA 3/3 · GUINCHO':V3.bell>0?'ETAPA 2/3 · PIPOCA':'ETAPA 1/3 · SINO';if(id==='marshLights')return V3.marshLights.filter(v=>v>0).length+'/3 LUMES';if(id==='glassArray')return V3.mirrorAngles.filter((v,i)=>v===V3.mirrorTarget[i]).length+'/3 ALINHADOS';if(id==='tidalLock')return v3InletOpen()?'ETAPA 2/2 · CORRENTE':'ETAPA 1/2 · VÁLVULA';return ''}
function v3Discover(id){const s=v3State();if(!v3Own(V3_SITES,id)||s.known.includes(id))return;s.known.push(id);V3.metrics.discoveries=(V3.metrics.discoveries||0)+1;toast('Caminho encontrado: '+V3_SITES[id].name+'. Consulte o Di\u00e1rio.','gold');sound('secret',.6);saveGame()}
function v3Solve(id){if(!v3Own(V3_SITES,id)||v3Solved(id))return false;const state=v3State();if(!state.known.includes(id))state.known.push(id);state.solved.push(id);V3.metrics.puzzles++;if(V3.track===id)V3.track=null;if(id==='birdsong')v3ReleaseBird(false);if(id==='glassArray'&&!G.secrets.includes('glassGarden'))discoverSecret('glassGarden',true);if(id==='marshLights')V3.marshLights=[999,999,999];if(id==='glassArray')V3.mirrorAngles=[...V3.mirrorTarget];burst(V3_SITES[id].x,V3_SITES[id].y,'#e6cc8a',24,85);sound('quest',.9);v3Say('RESOLVIDO · '+V3_SITES[id].name,4);toast(V3_SITES[id].name+': caminho resolvido.','gold');pulseQuestHUD();saveGame();return true}
function v3ResetTransient(){V3.plate=0;V3.bell=0;V3.hold=0;V3.birdTask=false;V3.birdArrived=false;V3.valve=0;V3.anchorTension=0;V3.marshLights=v3Solved('marshLights')?[999,999,999]:[0,0,0];V3.mirrorAngles=v3Solved('glassArray')?[...V3.mirrorTarget]:[0,0,0];V3.bogWait=0;V3.bogWarning=null;V3.bogCooldown=0;V3.lastPlayer=null;V3.message='';V3.messageUntil=0;V3.lastCue='';V3.lastPlateActive=false;V3.lastValveActive=false;V3.lastLampState=V3.marshLights.map(v=>v>0);V3.feedback={id:null,kind:'',label:'',until:0};V3.misses={};V3.rescueCooldown=0;const load=v3Object('v3-load');if(load){load.x=1730;load.y=2000}if(bird){bird.scoutTarget=null;bird.hintTime=0}}
function v3BuildWorld(){V3.track=null;V3.metrics={puzzles:0,coverBlocks:0,bogWarnings:0,bogHits:0,tideRescues:0,hookLocks:0,hookMissHints:0,mechanismCues:0};V3.objects=V3_OBJECTS.map(o=>({...o,kind:'rigging'}));v3ResetTransient();V3.lastSeals=G.seals.join(',');V3.lastBoss=G.bossDefeated;for(const o of V3.objects)structures.push(o);for(const [id,s]of V3_SITE_ENTRIES)structures.push({id:'v3-board-'+id,kind:'worldBoard',site:id,x:s.board.x,y:s.board.y,r:18,name:s.name});structures.push({id:'v3-reef-anchor',kind:'grappleAnchor',x:4960,y:2770,r:18,name:'Argola da margem leste',v3:true});
 // Preserve RNG order, quest IDs and loot: clear decoration only after generation.
 const clear=p=>V3_SITE_LIST.some(s=>dist(p,s)<300)||V3_WALLS.some(b=>v3InRect(p.x,p.y,b,75))||V3_COVERS.some(b=>v3InRect(p.x,p.y,b,45))||V3_BRUSH.some(b=>v3Inside(p.x,p.y,b,12))||V3_BOGS.some(b=>v3Inside(p.x,p.y,b,25));scenery=scenery.filter(s=>!clear(s));staticGrid.clear();for(const s of scenery)if(s.collision)gridAdd(s);for(const e of [...props,...structures.filter(s=>s.kind==='chest'),...enemies]){if(!v3SolidAt(e.x,e.y,e.r||14))continue;const safe=v3FindSafe(e.x,e.y,e.r||14);if(safe){e.x=safe.x;e.y=safe.y;if(e.homeX!==undefined){e.homeX=e.x;e.homeY=e.y}}}}
function v3FindSafe(x,y,r=12){if(walkable(x,y,r))return {x,y};for(let d=20;d<=460;d+=16)for(let i=0;i<32;i++){const a=i/32*TAU,nx=x+Math.cos(a)*d,ny=y+Math.sin(a)*d;if(walkable(nx,ny,r))return{x:nx,y:ny}}return null}
function v3RecoverPosition(silent=false){if(walkable(player.x,player.y,player.r))return false;const q=v3FindSafe(player.x,player.y,player.r)||{x:HOME.x+27,y:HOME.y+83};player.x=q.x;player.y=q.y;cam.x=q.x;cam.y=q.y;hook=null;player.dashTime=0;player.invuln=Math.max(1,player.invuln);if(bird){bird.x=q.x+20;bird.y=q.y-40}const announce=!silent&&V3.rescueCooldown<=0;if(announce){V3.metrics.tideRescues++;V3.rescueCooldown=2.4;toast('A passagem fechou. Pipoca guiou Nilo at\u00e9 a margem segura.')}return true}
function v3ReleaseBird(notify=true){if(!V3.birdTask)return;V3.birdTask=false;V3.hold=0;V3.birdArrived=false;if(bird){bird.manualCD=Math.max(bird.manualCD,.8);bird.autoTimer=Math.max(bird.autoTimer,.8)}if(notify)v3Say('Pipoca soltou a trava. Puxe o sino para tentar de novo.')}
function v3BirdCommand(){if(V3.birdTask){v3ReleaseBird();return true}if(v3Solved('birdsong'))return false;const perch=v3Object('v3-perch');if(!perch||dist(player,perch)>300)return false;const aimed=pointer.known&&dist({x:cam.x+(pointer.x-width/2)/zoom,y:cam.y+(pointer.y-height/2)/zoom},perch)<95,mechanismIntent=V3.bell>0&&dist(player,perch)<270;if(!aimed&&!mechanismIntent&&(player.combat>0||nearestEnemy(player,155)))return false;if(V3.bell<=0)return false;if(bird.manualCD>.05){v3Say('Pipoca ainda est\u00e1 recuperando o f\u00f4lego.');return true}V3.birdTask=true;V3.birdArrived=false;V3.hold=11;bird.scoutTarget=null;bird.hintTime=0;sound('bird',.6);v3Say('Pipoca vai segurar a trava. Prepare o guincho.',4);return true}
function v3BirdUpdate(dt){if(!V3.birdTask)return false;const p=v3Object('v3-perch');if(!p||player.hp<=0||dist(player,p)>465){v3ReleaseBird(false);return false}bird.manualCD=Math.max(0,bird.manualCD-dt);bird.attackAnim=Math.max(0,bird.attackAnim-dt);bird.x=lerp(bird.x,p.x,Math.min(1,dt*6));bird.y=lerp(bird.y,p.y-39,Math.min(1,dt*6));if(dist(bird,{x:p.x,y:p.y-39})<12){V3.birdArrived=true;V3.hold=Math.max(0,V3.hold-dt)}if(V3.hold<=0){V3.bell=0;v3ReleaseBird();return false}return true}
function v3ExpectedObject(id){if(id==='counterweight')return v3Object(V3.plate>=.45?'v3-lock':'v3-load');if(id==='birdsong')return v3Object(V3.birdTask?'v3-winch':'v3-bell');if(id==='marshLights'){const i=V3.marshLights.findIndex(v=>v<=0);return v3Object('v3-lamp-'+['a','b','c'][i<0?0:i])}if(id==='glassArray'){const i=V3.mirrorAngles.findIndex((v,k)=>v!==V3.mirrorTarget[k]);return v3Object('v3-mirror-'+['a','b','c'][i<0?0:i])}if(id==='tidalLock')return v3Object(player.x>4910?'v3-chain':'v3-valve');return null}
function v3Hookable(s){return s.kind==='rigging'&&s.role!=='perch'&&!v3Solved(s.site)}
function v3HookAim(){if(pointer.known){const p={x:cam.x+(pointer.x-width/2)/zoom,y:cam.y+(pointer.y-height/2)/zoom};const target=V3.objects.find(s=>v3Hookable(s)&&dist(p,s)<35&&dist(player,s)<hookRange());if(target)return angle(player,target);return currentAim()}if(v3Touch()&&player.combat<=0){const candidates=Object.keys(V3_SITES).filter(id=>!v3Solved(id)).map(v3ExpectedObject).filter(Boolean),target=candidates.filter(s=>dist(player,s)<hookRange()-8&&Math.abs(Math.atan2(Math.sin(angle(player,s)-player.angle),Math.cos(angle(player,s)-player.angle)))<1.05).sort((a,b)=>dist(player,a)-dist(player,b))[0];if(target)return angle(player,target)}return currentAim()}
function v3Pull(o){v3Discover(o.site);G.tutorial.reeled=true;V3.misses[o.site]=0;if(o.role==='lock'){if(V3.plate>=.45){v3ObjectCue(o,'TRAVA FIXADA','ok');v3Solve('counterweight')}else{v3ObjectCue(o,'TRAVA BLOQUEADA','warn');v3Say('A trava está sob tensão. Primeiro coloque o lastro na placa.')}}else if(o.role==='bell'){V3.bell=22;sound('secret',.72);v3ObjectCue(o,'SINO ATIVO','ok');const perch=v3Object('v3-perch');if(perch)v3Pulse(perch.id,'hint','CHAME PIPOCA',2.2);v3Say('Sino ativo. Agora mande Pipoca segurar a trava no poleiro.',5)}else if(o.role==='winch'){if(V3.birdTask&&V3.birdArrived&&V3.hold>0){v3ObjectCue(o,'GUINCHO LIBERADO','ok');v3Solve('birdsong')}else{v3ObjectCue(o,'GUINCHO TRAVADO','warn');const perch=v3Object('v3-perch');if(perch)v3Pulse(perch.id,'hint','TRAVA SEM APOIO',1.8);v3Say('O guincho está travado. Falta alguém segurar a trava lá em cima.')}}else if(o.role==='valve'){if(lowTideOpen()||G.bossDefeated){V3.valve=24;v3ObjectCue(o,'VÁLVULA ABERTA · 24 s','ok',1.6);const chain=v3Object('v3-chain');if(chain)v3Pulse(chain.id,'hint','DEPOIS: CORRENTE',2);v3Say('Passagem drenada por 24 s. Cruze e puxe a corrente pelo lado leste.',5)}else{v3ObjectCue(o,'PRESSÃO DA MARÉ','warn');v3Say('A maré empurra a válvula. Espere a vazante ou use a argola do Navegador.',5)}}else if(o.role==='lamp'){V3.marshLights[o.slot]=10;sound('secret',.65);const lit=V3.marshLights.filter(v=>v>0).length;v3ObjectCue(o,'LUME '+lit+'/3','ok',1.4);v3Say('Lume '+(o.slot+1)+' aceso · '+lit+'/3. Os outros continuam contando.',3.8);if(V3.marshLights.every(v=>v>0))v3Solve('marshLights')}else if(o.role==='mirror'){V3.mirrorAngles[o.slot]=(V3.mirrorAngles[o.slot]+1)%4;sound('reel',.72);const ok=V3.mirrorAngles[o.slot]===V3.mirrorTarget[o.slot],aligned=V3.mirrorAngles.filter((v,i)=>v===V3.mirrorTarget[i]).length;v3ObjectCue(o,ok?'ALINHADO · '+aligned+'/3':'GIRO REGISTRADO · '+aligned+'/3',ok?'ok':'hit',1.45);v3Say(o.name+': '+(ok?'marca alinhada. ':'reflexo girou um quarto de volta. ')+aligned+'/3 alinhados.',3.5);if(V3.mirrorAngles.every((v,i)=>v===V3.mirrorTarget[i]))v3Solve('glassArray')}else if(o.role==='chain'){if(!(V3.valve>0||V3.anchorTension>0||G.bossDefeated)){v3ObjectCue(o,'CORRENTE SEM TENSÃO','warn');v3Say('A corrente está frouxa. Ative a válvula ou cruze pela argola do Navegador antes de fixar.')}else if(player.x>o.x+38&&Math.abs(player.y-o.y)<110){v3ObjectCue(o,'CORRENTE FIXADA','ok');v3Solve('tidalLock')}else{v3ObjectCue(o,'LADO ERRADO','warn');v3Say('Puxe PARA FORA: fique a leste da corrente, no lado da seta.')}}sound('reel',.8);hook=null;player.hookCD=hookCooldown()*.7}
function v3ReelWeight(h,dt){const o=h.target;if(o?.kind!=='rigging'||o.role!=='weight')return false;const d=dist(o,player),stop=player.r+o.r+9;if(d>stop+1){const a=angle(o,player),step=Math.min((245+player.skills.line*20)*dt,d-stop),x=o.x,y=o.y;moveEntity(o,Math.cos(a)*step,Math.sin(a)*step);h.x=o.x;h.y=o.y;if(Math.hypot(o.x-x,o.y-y)<.04)h.blockTime=(h.blockTime||0)+dt;else h.blockTime=0;if(h.blockTime>.35){v3ObjectCue(o,'OBSTRUÍDO','warn');v3Say('O lastro encostou num obstáculo. Tente puxar de outro ângulo.');hook=null;player.hookCD=hookCooldown()}}else{v3ObjectCue(o,'LASTRO REPOSICIONADO','hit',.9);hook=null;player.hookCD=hookCooldown();G.tutorial.reeled=true}return true}
function v3StepText(id){if(v3Solved(id))return 'RESOLVIDO · mecanismo estabilizado.';if(id==='counterweight')return V3.plate>=.45?'ETAPA 2/2 · A ponte baixou. A trava agora está liberada.':'ETAPA 1/2 · Puxe o lastro até o círculo; o mecanismo confirma quando o peso encaixa.';if(id==='birdsong')return V3.birdTask?(V3.birdArrived?'ETAPA 3/3 · Pipoca segura por '+Math.ceil(V3.hold)+' s. Puxe o guincho!':'ETAPA 2/3 · Pipoca está chegando ao poleiro.'):V3.bell>0?'ETAPA 2/3 · '+v3Key('bird')+': mande Pipoca segurar a trava.':'ETAPA 1/3 · Puxe o sino para acordar o mecanismo.';if(id==='marshLights')return 'LUMES · '+V3.marshLights.filter(v=>v>0).length+'/3 acesos. Cada luz mostra seu tempo restante.';if(id==='glassArray'){const ok=V3.mirrorAngles.filter((v,i)=>v===V3.mirrorTarget[i]).length;return 'ESPELHOS · '+ok+'/3 alinhados. O risco dourado é o alvo; cada puxão gira 90°.'}return v3InletOpen()?'ETAPA 2/2 · passagem aberta. Cruze e puxe a corrente pelo lado leste.':lowTideOpen()?'ETAPA 1/2 · maré baixa. Abra a válvula para drenar a passagem.':'ETAPA 1/2 · válvula sob pressão. Aguarde a vazante ou use a argola do Navegador.'}
function v3NearestSite(radius=340){return V3_SITE_ENTRIES.map(([id,s])=>({id,...s})).filter(s=>dist(player,s)<radius).sort((a,b)=>dist(player,a)-dist(player,b))[0]||null}
function v3ResetSite(id){if(v3Solved(id))return;hook=null;player.hookCD=0;if(id==='counterweight'){const o=v3Object('v3-load');o.x=1730;o.y=2000;V3.plate=0}else if(id==='birdsong'){v3ReleaseBird(false);V3.bell=0}else if(id==='marshLights'){V3.marshLights=[0,0,0]}else if(id==='glassArray'){V3.mirrorAngles=[0,0,0]}else if(id==='tidalLock'){V3.valve=0;V3.anchorTension=0;}v3RecoverPosition(true);v3Say('Mecanismo reposicionado. Nada foi gasto.')}
function v3ShowGuide(id){if(!v3Own(V3_SITES,id))return;v3Discover(id);const s=V3_SITES[id],html=modalHeader('CAMINHOS DA ILHA',s.name)+`<p>${s.clue}</p><div class="v3-guide-state">${v3StepText(id)}</div><p class="v3-reward">${icon('hook')} ${s.reward} Sem exig\u00eancia para a campanha principal.</p><div class="modal-actions"><button id="v3-guide-track" class="primary">${v3Solved(id)?'Voltar \u00e0 ilha':'Marcar no mapa'}</button>${v3Solved(id)?'':`<button id="v3-guide-reset" class="secondary">Reposicionar mecanismo</button>`}</div><div class="footer-note">${v3Key('hook')}: arremessar; novamente para puxar. ${v3Key('bird')}: comandar Pipoca. As tentativas não consomem itens. O alvo do gancho confirma quando foi preso; mecanismos respondem visualmente a cada mudança. Ao sair da aventura, estados temporários voltam ao início; soluções registradas permanecem.</div>`;setModal('worldGuide',html,true);$('v3-guide-track').onclick=()=>{V3.track=v3Solved(id)?null:id;closeOverlay()};const reset=$('v3-guide-reset');if(reset)reset.onclick=()=>{v3ResetSite(id);closeOverlay()}}
function v3JournalHTML(){const state=v3State();return `<section class="v3-journal"><div class="eyebrow">CAMINHOS DA ILHA \u00b7 ${state.solved.length}/${V3_SITE_ENTRIES.length}</div><p>Os mecanismos antigos respondem ao gancho, ao peso, a Pipoca, à luz e à maré. Explore ao norte do abrigo, no noroeste do Bosque, no Brejo, nas Dunas e na costa leste do Recife.</p><div class="v3-journal-grid">`+V3_SITE_ENTRIES.map(([id,s])=>state.known.includes(id)?`<button class="v3-journal-card ${v3Solved(id)?'done':''}" data-v3-guide="${id}"><span>${v3Solved(id)?'PASSAGEM ABERTA':'MECANISMO ENCONTRADO'}</span><strong>${s.name}</strong><small>${v3StepText(id)}</small></button>`:`<div class="v3-journal-card unknown"><span>${{meadow:'CAMPOS',forest:'BOSQUE',marsh:'BREJO',dunes:'DUNAS',reef:'RECIFE'}[s.zone]}</span><strong>Caminho por encontrar</strong><small>Procure a placa de cordame na regi\u00e3o.</small></div>`).join('')+`</div><div class="v3-biome-notes"><b>Leia o terreno</b><p>Campos: as rajadas desviam disparos leves; procure o lado protegido das cercas. Bosque: a vegeta\u00e7\u00e3o baixa esconde quem n\u00e3o iniciou combate. Brejo: use as pedras luminosas; bolhas avisam antes de explodir. Dunas: destro\u00e7os bloqueiam disparos comuns. Recife: a vazante abre caminhos tempor\u00e1rios.</p><p>Os selos retiram ra\u00edzes, estabilizam o Brejo e destravam a grade de Bronze. Derrotar Esponj\u00e3o tamb\u00e9m acalma a eclusa. Os ciclos da mar\u00e9 continuam.</p></div></section>`}
function v3BindJournal(){for(const b of document.querySelectorAll('[data-v3-guide]'))b.onclick=()=>v3ShowGuide(b.dataset.v3Guide)}
function v3MapMarkers(c,sx,sy,large=false){for(const id of v3State().known){const s=V3_SITES[id],x=s.x*sx,y=s.y*sy;c.save();c.translate(x,y);c.rotate(Math.PI/4);rr(c,-(large?6:12),-(large?6:12),large?12:24,large?12:24,2,v3Solved(id)?'#a8c8a7':'#e5c37c','#244d40',large?2:4);c.restore();if(large){c.textAlign='center';c.font="10px 'Trebuchet MS',Arial";c.fillStyle='#f4e4b9';c.fillText(s.name,x,y-15)}}}
function v3UpdateHUD(){const box=$('world-cue');if(!box||!G.started)return;const site=v3NearestSite(),z=zoneAt(player.x,player.y).id,bog=v3BogAt(player),hiding=v3Hidden(player)&&player.combat<=0;let head='',body='',detail='',target=null;if(V3.messageUntil>G.playTime){head='CORDAME';body=V3.message}else if(site){head=site.name;body=v3StepText(site.id);target=v3ExpectedObject(site.id);if(!v3Solved(site.id))detail=v3PuzzleProgress(site.id)+' · '+v3Key('interact')+': ajuda · '+v3Key('hook')+': prender / puxar'}else if(V3.track){head='CAMINHO MARCADO';body=V3_SITES[V3.track].name+' \u00b7 '+Math.round(dist(player,V3_SITES[V3.track])/10)+' m'}else if(bog){head=V3.bogWarning?'BOLHAS \u00b7 SAIA DO C\u00cdRCULO':'TERRENO INST\u00c1VEL';body='As pedras claras s\u00e3o firmes. Ficar parado no lodo atrai bolhas.'}else if(hiding){head='ENTRE AS FOLHAS';body='Oculto para amea\u00e7as distantes. Atacar ou chegar muito perto revela Nilo.'}else if((z==='meadow'||z==='dunes')&&!v3SafeArena(player)&&['wind','storm'].includes(weatherNow().id)){head=v3Sheltered(player)?'A SOTAVENTO':'RAJADAS';body=v3Sheltered(player)?'A cobertura corta o vento.':'O vento carrega Nilo em movimento e curva disparos leves.'}else if(z==='dunes'&&v3Sheltered(player)){head='COBERTURA';body='Destro\u00e7os barram disparos comuns. Ataques de \u00e1rea ainda alcan\u00e7am voc\u00ea.'}const boss=enemies.some(e=>!e.dead&&(e.boss&&e.awake||e.guardian&&e.aggro)&&dist(player,e)<500);const visible=!!head&&!G.overlay&&!boss;box.classList.toggle('hidden',!visible);document.body.classList.toggle('v3-cue-active',visible);box.classList.toggle('v3-danger',!!V3.bogWarning&&!!bog);const html=`<span>${head}</span><p>${body}</p>${detail?'<small>'+detail+'</small>':''}`;if(html!==V3.lastCue){box.innerHTML=html;V3.lastCue=html}if(nearby?.kind==='worldBoard'&&!executionTarget){$('interact-text').textContent='Ler placa: '+nearby.name;$('touch-interact').textContent='Ler placa'}V3.target=target}
function v3Update(dt){V3.rescueCooldown=Math.max(0,(V3.rescueCooldown||0)-dt);if(player.hp<=0){v3ReleaseBird(false);V3.bogWarning=null;return;}V3.bell=Math.max(0,V3.bell-dt);V3.valve=Math.max(0,V3.valve-dt);V3.anchorTension=Math.max(0,V3.anchorTension-dt);if(!v3Solved('marshLights'))for(let i=0;i<V3.marshLights.length;i++){const was=V3.marshLights[i]>0;V3.marshLights[i]=Math.max(0,V3.marshLights[i]-dt);const on=V3.marshLights[i]>0;if(was&&!on){const lamp=v3Object('v3-lamp-'+['a','b','c'][i]);if(lamp)v3ObjectCue(lamp,'LUME APAGOU','warn',1.2);v3Say('Um dos lumes apagou. A sequência continua, mas ele precisa ser reacendido.',2.8)}V3.lastLampState[i]=on}V3.bogCooldown=Math.max(0,V3.bogCooldown-dt);const o=v3Object('v3-load');V3.plate=o&&dist(o,V3_PLATE)<V3_PLATE.r?Math.min(1,V3.plate+dt):0;const plateActive=V3.plate>=.45;if(plateActive&&!V3.lastPlateActive&&!v3Solved('counterweight')){V3.lastPlateActive=true;v3ObjectCue(o,'CLAC · PONTE BAIXOU','ok',1.8);const lock=v3Object('v3-lock');if(lock)v3Pulse(lock.id,'hint','AGORA: TRAVA',2.2);sound('secret',.72);v3Say('O lastro encaixou. A ponte baixou; a trava está pronta.',4.5)}else if(!plateActive&&V3.lastPlateActive&&!v3Solved('counterweight')){V3.lastPlateActive=false;v3Say('O lastro saiu da placa. A ponte voltou a subir.',2.6)}if(V3.valve>0&&!lowTideOpen()&&!G.bossDefeated)V3.valve=0;const valveActive=V3.valve>0;if(valveActive&&!V3.lastValveActive){V3.lastValveActive=true}else if(!valveActive&&V3.lastValveActive&&!v3Solved('tidalLock')){V3.lastValveActive=false;v3Say('A eclusa voltou a encher. Ative a válvula novamente.',2.8)}if(player.hp>0&&v3SolidAt(player.x,player.y,player.r)&&!(hook?.target?.id==='v3-reef-anchor'&&hook.mode==='reeling'))v3RecoverPosition();for(const [id,s]of V3_SITE_ENTRIES)if(dist(player,s)<295)v3Discover(id);if(V3.birdTask&&player.hp<=0)v3ReleaseBird(false);const bog=v3BogAt(player),moved=V3.lastPlayer?dist(player,V3.lastPlayer):0;if(bog&&player.hp>0&&player.dashTime<=0&&V3.bogCooldown<=0){V3.bogWait=moved<dt*30?V3.bogWait+dt:Math.max(0,V3.bogWait-dt*1.2);if(V3.bogWait>(equipped('wet_boots')?2.9:1.65)&&!V3.bogWarning){V3.bogWarning={type:'spore',x:player.x,y:player.y,age:0,wait:1.15,r:47};V3.metrics.bogWarnings++;V3.bogWait=0}}else V3.bogWait=0;if(V3.bogWarning){const w=V3.bogWarning;w.age+=dt;if(w.age>=w.wait){if(player.hp>0&&dist(player,w)<w.r+player.r){hurtPlayer(8,w);V3.metrics.bogHits++}burst(w.x,w.y,'#a9c69a',9,60);V3.bogWarning=null;V3.bogCooldown=3.8}}V3.lastPlayer={x:player.x,y:player.y};const seals=G.seals.join(',');if(seals!==V3.lastSeals){const fresh=G.seals.filter(s=>!V3.lastSeals.split(',').includes(s));V3.lastSeals=seals;for(const s of fresh)toast({moss:'As ra\u00edzes recuaram no limite do Bosque. Um caminho reapareceu.',mire:'O selo firmou o lodo a oeste do Brejo. As pedras agora formam um caminho seguro.',bronze:'A grade antiga das Dunas se abriu na dire\u00e7\u00e3o do Recife.'}[s],'gold')}if(G.bossDefeated&&!V3.lastBoss){V3.lastBoss=true;toast('Sem o rei, a eclusa do Recife deixou de lutar contra a mar\u00e9.','gold')}}
function v3DrawArrow(c,x,y,a,color='#e2c887',size=15){c.save();c.translate(x,y);c.rotate(a);line(c,[[-size,0],[size,0],[size-5,-5]],color,2);line(c,[[size,0],[size-5,5]],color,2);c.restore()}
function v3Visible(x,y,pad=180){return Math.abs(x-cam.x)<width/zoom/2+pad&&Math.abs(y-cam.y)<height/zoom/2+pad}
function v3DrawBarrier(c,b){if(!v3Visible(b.x+b.w/2,b.y+b.h/2,230))return;const open=v3WallOpen(b),horizontal=b.axis==='x',segments=open?(horizontal?[{...b,w:b.gap[0]-b.x},{...b,x:b.gap[1],w:b.x+b.w-b.gap[1]}]:[{...b,h:b.gap[0]-b.y},{...b,y:b.gap[1],h:b.y+b.h-b.gap[1]}]):[b];if(b.type==='ravine'||b.type==='inlet'){rr(c,b.x-5,b.y-5,b.w+10,b.h+10,11,b.type==='inlet'?'#5d9d97':'#9b9871');rr(c,b.x,b.y,b.w,b.h,8,b.type==='inlet'?'#326d69':'#334d42');if(b.type==='inlet'){for(let i=0;i<10;i++){const y=b.y+19+i*30;line(c,[[b.x+12,y],[b.x+b.w-14,y+5]],'#b2d4bf55',2)}}else for(let i=0;i<9;i++)line(c,[[b.x+5,b.y+20+i*35],[b.x+21,b.y+32+i*35]],'#203d34',3);if(open){const gy=b.gap[0],gh=b.gap[1]-gy;rr(c,b.x-9,gy,b.w+18,gh,3,'#8a8257','#ded09d',2);for(let x=b.x-5;x<b.x+b.w+10;x+=13)line(c,[[x,gy+4],[x,gy+gh-4]],'#d7bf83',8);line(c,[[b.x-12,gy+4],[b.x+b.w+12,gy+4]],'#6d6243',3);line(c,[[b.x-12,gy+gh-4],[b.x+b.w+12,gy+gh-4]],'#6d6243',3)}return}for(const s of segments){if(b.type==='roots'){rr(c,s.x,s.y,s.w,s.h,9,'#365b43');const len=Math.max(s.w,s.h);for(let i=0;i<len;i+=21){const x=s.x+(horizontal?i:s.w/2),y=s.y+(horizontal?s.h/2:i);line(c,[[x-13,y-10],[x+9,y+2],[x-8,y+17]],'#85a16d',5);ellipse(c,x+10,y-4,14,6,'#8fa879',-.5)}}else{rr(c,s.x,s.y,s.w,s.h,3,'#696b4c','#c9b975',2);for(let x=s.x+7;x<s.x+s.w;x+=17)line(c,[[x,s.y-8],[x,s.y+s.h+7]],'#d0b778',5)}}if(open){const x=horizontal?(b.gap[0]+b.gap[1])/2:b.x+b.w/2,y=horizontal?b.y+b.h/2:(b.gap[0]+b.gap[1])/2;if(dist(player,{x,y})<145)worldLabel(x,y+17,'CAMINHO LIBERADO','#e9d99f',8)}}
function v3DrawGround(){if(!terrain)return;const c=ctx;for(const b of V3_BOGS){if(!v3Visible(b.x,b.y,230))continue;const drained=b.drains&&G.seals.includes('mire');ellipse(c,b.x,b.y,b.rx+8,b.ry+7,drained?'#80996b':'#447d6b');ellipse(c,b.x,b.y,b.rx,b.ry,drained?'#9baa75':'#37675b');if(!drained)for(let i=0;i<9;i++){const a=i*2.4,r=.35+(i%3)*.2;circle(c,b.x+Math.cos(a)*b.rx*r,b.y+Math.sin(a)*b.ry*r,4+i%3,'#8daa8060')}}for(const s of V3_STONES)if(v3Visible(s.x,s.y)){ellipse(c,s.x+2,s.y+4,s.r+2,s.r*.62,'#254a3e66');ellipse(c,s.x,s.y,s.r,s.r*.65,'#a7b795');ellipse(c,s.x-3,s.y-4,14,6,'#d3d9ad');circle(c,s.x+8,s.y-3,2.5,'#eff0b8')}for(const b of V3_BRUSH){if(!v3Visible(b.x,b.y))continue;ellipse(c,b.x,b.y,b.rx,b.ry,'#356a4548');for(let i=0;i<21;i++){const a=i*2.4,r=.3+(i%4)*.16,x=b.x+Math.cos(a)*b.rx*r,y=b.y+Math.sin(a)*b.ry*r;line(c,[[x-4,y],[x-5,y-10],[x,y-6],[x+4,y-14]],'#416f47',2);ellipse(c,x+3,y-9,6,3,'#96b47a',-.6)}}for(const b of V3_WALLS)v3DrawBarrier(c,b);for(const b of V3_COVERS){if(!v3Visible(b.x,b.y))continue;rr(c,b.x+4,b.y+6,b.w,b.h,5,'#2d504541');rr(c,b.x,b.y-6,b.w,b.h+6,4,b.type==='hedge'?'#557d4a':b.type==='stone'?'#b9ad77':'#938051','#cebd85',2);const horizontal=b.w>b.h;for(let i=8;i<Math.max(b.w,b.h);i+=16){const x=b.x+(horizontal?i:3),y=b.y+(horizontal?2:i);line(c,[[x,y],[x+(horizontal?0:b.w-6),y+(horizontal?b.h-4:0)]],'#d1b87b',3)}}if(v3Visible(V3_PLATE.x,V3_PLATE.y)){circle(c,V3_PLATE.x,V3_PLATE.y,29,'#334f4040',V3.plate>=.45?'#dfce87':'#b9b28a',2);circle(c,V3_PLATE.x,V3_PLATE.y,23,'#a89d6f',V3.plate>=.45?'#e8da9c':'#ddd4a4',2);line(c,[[V3_PLATE.x,V3_PLATE.y],[1880,2000],[1880,1960],[1910,1960]],'#c4af79',2);if(!v3Solved('counterweight')){ellipse(c,1855,1995,5,9,'#eddda780',-.2);ellipse(c,1855,2007,5,9,'#eddda780',.2);v3DrawArrow(c,1770,2000,0);if(V3.plate>=.45&&dist(player,V3_PLATE)<260)worldLabel(V3_PLATE.x,V3_PLATE.y+48,'PESO ENCAIXADO · PONTE BAIXA','#e7dfa1',9)}}const wind=v3WindData();for(const s of [V3_SITES.counterweight,{x:3900,y:2200}]){if(!v3Visible(s.x,s.y))continue;line(c,[[s.x-200,s.y-170],[s.x-200,s.y-209]],'#887952',3);v3DrawArrow(c,s.x-180,s.y-209,Math.atan2(wind.y,wind.x),'#dbcd8b',18)}if(v3Visible(5025,2840)&&!v3Solved('tidalLock'))v3DrawArrow(c,5015,2840,0,'#e9d39a',24);if(V3.bogWarning){const w=V3.bogWarning,q=clamp(w.age/w.wait,0,1);circle(c,w.x,w.y,w.r,'#c4b58e20','#e8d59a',2.5);circle(c,w.x,w.y,w.r*(1-q),null,'#e3b383',2);if(PREFS.telegraphLabels==='full')worldLabel(w.x,w.y-w.r-12,'BOLHAS \u00b7 SAIA','#ffe4ad',9)}}
function v3DrawObject(s){const c=ctx,x=s.x,y=s.y,solved=v3Solved(s.site);c.save();ellipse(c,x+2,y+4,22,8,'#274c3d44');if(s.kind==='worldBoard'){line(c,[[x,y+7],[x,y-27]],'#6c6545',5);rr(c,x-26,y-45,52,25,4,'#8f8458','#d2bf86',2);c.font='bold 17px Georgia';c.fillStyle='#f0dba1';c.textAlign='center';c.fillText(solved?'\u00b7':'?',x,y-27);if(dist(player,s)<155)worldLabel(x,y-61,V3_SITES[s.site].name,'#f0dfac',11);c.restore();return}if(s.role==='weight'){rr(c,x-19,y-28,38,33,4,'#7e8980','#c8c7a0',2);line(c,[[x-14,y-23],[x+13,y]],'#cad0ae',3);circle(c,x,y-25,7,null,'#e6d19a',3);line(c,[[x-12,y-10],[x+12,y-10]],'#afb698',2)}else if(s.role==='perch'){line(c,[[x,y+5],[x,y-54]],'#736a49',5);line(c,[[x-22,y-54],[x+22,y-54]],'#ceb479',5);line(c,[[x,y-35],[x+40,y-28],[1760,y-28]],V3.birdTask?'#ead79c':'#b3a276',2);if(V3.birdTask)worldLabel(x,y-73,(V3.birdArrived?Math.ceil(V3.hold)+' s':'PIPOCA'),'#f5e3b1',10);else if(V3.bell>0)worldLabel(x,y-76,v3Key('bird')+' \u00b7 SEGURAR','#e8dda8',9)}else if(s.role==='bell'){line(c,[[x-20,y+3],[x-20,y-46],[x+20,y-46],[x+20,y+3]],'#827447',4);c.beginPath();c.moveTo(x-15,y-17);c.quadraticCurveTo(x-9,y-40,x,y-35);c.quadraticCurveTo(x+10,y-39,x+15,y-17);c.closePath();c.fillStyle=V3.bell>0?'#e2c777':'#bdab6a';c.fill();circle(c,x,y-13,4,'#f0d898');line(c,[[x,y-12],[x,y+6]],'#e0cc92',2)}else if(s.role==='lamp'){const on=V3.marshLights[s.slot]>0;line(c,[[x,y+2],[x,y-30]],'#6c6545',5);circle(c,x,y-36,11,on?'#d9e998':'#607b68',on?'#f4efae':'#9eae8e',2);if(on){c.globalAlpha=.22+.11*Math.sin(G.time*5+s.slot);circle(c,x,y-36,31,'#e9efa0');c.globalAlpha=1;worldLabel(x,y-57,v3Solved('marshLights')?'ESTÁVEL':Math.ceil(V3.marshLights[s.slot])+' s','#e9e9a4',8)}else if(dist(player,s)<210&&!v3Solved('marshLights'))worldLabel(x,y-56,'APAGADO','#aeb9a0',8)}else if(s.role==='mirror'){const a=V3.mirrorAngles[s.slot]*Math.PI/2,target=V3.mirrorTarget[s.slot]*Math.PI/2,ok=V3.mirrorAngles[s.slot]===V3.mirrorTarget[s.slot];rr(c,x-16,y-9,32,11,4,'#807754','#bda96f',2);c.save();c.translate(x,y+5);for(let i=0;i<4;i++){const q=i*Math.PI/2,tx=Math.cos(q)*18,ty=Math.sin(q)*18;circle(c,tx,ty,i===V3.mirrorTarget[s.slot]?3.8:2.2,i===V3.mirrorTarget[s.slot]?'#efd47e':'#7e806d')}c.rotate(target);line(c,[[8,0],[23,0]],'#f1ce76',3);c.restore();c.save();c.translate(x,y-25);c.rotate(a);rr(c,-3,-19,6,38,2,ok?'#e5dca6':'#aeb9a0','#f4e7b5',1.5);line(c,[[0,-14],[0,14]],'#ffffff88',1);if(ok){c.globalAlpha=.25;rr(c,-8,-24,16,48,6,'#f2e6a2');c.globalAlpha=1}c.restore();if(ok&&dist(player,s)<220)worldLabel(x,y-54,'ALINHADO','#e9e7a3',8)}else{rr(c,x-20,y-23,40,28,5,'#7e8058','#c5b781',2);circle(c,x,y-19,14,'#566956',solved?'#acd1b5':'#e0c68a',3);for(let i=0;i<4;i++){const a=i*Math.PI/2+(s.role==='valve'?Math.PI/4:0);line(c,[[x,y-19],[x+Math.cos(a)*12,y-19+Math.sin(a)*12]],'#dfcc92',2)}circle(c,x,y-19,4,'#f1d89a');if(s.role==='chain')line(c,[[x+18,y-4],[x+37,y-4]],'#c2b187',3)}const fb=s.feedbackUntil>G.playTime,rel=v3TargetRelevant(s),selected=V3.target?.id===s.id;if(!solved&&dist(player,s)<245&&(rel||fb||selected)){const pulse=1+Math.sin(G.time*7+s.x)*.12,kind=fb?s.feedbackKind:(selected?'hit':'hint'),color=kind==='ok'?'#e5e99b':kind==='warn'?'#e9a77e':'#efd69a';c.globalAlpha=fb?1:.72;circle(c,x,y+6,29*pulse,null,color,fb?2.8:1.8);c.globalAlpha=1;if(fb&&s.feedbackLabel)worldLabel(x,y-(s.role==='bell'?84:68),s.feedbackLabel,color,9)}if(!solved&&s.role!=='perch'&&dist(player,s)<215){c.globalAlpha=selected?1:.75;circle(c,x,y+6,24,null,selected?'#f0dba1':'#bbc5a3',1.4);worldLabel(x,y-(s.role==='bell'?68:51),s.name,'#ebdfb7',9)}c.restore()}
function v3SelfTest(){const errors=[],clean=v3CleanState(v3State());if(JSON.stringify(clean)!==JSON.stringify(v3State()))errors.push('invalid-exploration-state');const rigging=G.started?V3.objects:V3_OBJECTS;if(new Set(rigging.map(o=>o.id)).size!==V3_OBJECTS.length)errors.push('rigging-ids');for(const s of Object.values(V3_SITES))if(!landAt(s.board.x,s.board.y,25))errors.push('board-off-land');if(V3.birdTask&&(!Number.isFinite(V3.hold)||V3.hold<0))errors.push('bird-hold');if(V3.marshLights.length!==3||V3.mirrorAngles.length!==3)errors.push('puzzle-state');if(!V3.feedback||typeof V3.feedback.until!=='number')errors.push('puzzle-feedback');return errors}
function v3Report(){return {build:BUILD_ID,save:CURRENT_SAVE_VERSION,state:JSON.parse(JSON.stringify(v3State())),tracked:V3.track,biomes:{hidden:v3Hidden(player),bog:v3BogAt(player)?.id||null,sheltered:v3Sheltered(player),wind:v3WindData()},mechanisms:{plate:+V3.plate.toFixed(2),bell:+V3.bell.toFixed(2),pigeon:+V3.hold.toFixed(2),valve:+V3.valve.toFixed(2),anchorTension:+V3.anchorTension.toFixed(2),inlet:v3InletOpen()},metrics:{...V3.metrics}}}




