// Mantém ameaça na ilha, mas cria respiração entre combate, descoberta e travessia.
const ENCOUNTER_RHYTHM={wasCombat:false,respiteUntil:0,pressureUntil:0,starts:[],lastEventType:'',lastEventAt:-999,lastQuietKey:'',quietEntries:0,relocated:0,pressureTriggers:0,eventDeferrals:0,nonCombatSwaps:0};
const RHYTHM_COMBAT_EVENTS=new Set(['ambush','crabs','rareWisp','shipwreck','countertide']);
const RHYTHM_QUIET_RADII={camp:300,npc:190,worldBoard:225,livingMystery:155,livingInteract:150,livingBirdSpot:135,livingMysteryFinal:200,rhythmMoment:150,secret:115,waystone:105};
