function encounterRhythmQuietStructureAt(p,extra=0){if(!p||!Array.isArray(structures))return null;let best=null,bestD=Infinity;for(const s of structures){if(!s||s.hidden)continue;const r=RHYTHM_QUIET_RADII[s.kind];if(!r)continue;const d=dist(p,s);if(d<r+extra&&d<bestD){best=s;bestD=d}}return best?{structure:best,distance:bestD,radius:(RHYTHM_QUIET_RADII[best.kind]||0)+extra}:null}
function encounterRhythmQuietPoint(p,extra=0){return encounterRhythmQuietStructureAt(p,extra)}
function encounterRhythmSpecialThreatNear(p=player,range=330){return enemies.some(e=>!e.dead&&(e.boss&&e.awake||e.guardian||e.miniBossId)&&dist(e,p)<range)}
function encounterRhythmEnemySafe(e,d=dist(e,player)){if(!e||e.dead||e.boss||e.guardian||e.miniBossId||e.mini||e.eventId||e.tideSpawn||e.bossMinion||e.guardianMinion)return false;if(e.hp<e.maxHp-.5)return false;if(d<=92)return false;if(encounterRhythmSpecialThreatNear(player,360))return false;const quiet=encounterRhythmQuietStructureAt(player,0);if(quiet)return true;if(G.playTime<ENCOUNTER_RHYTHM.respiteUntil&&d>105)return true;if(G.playTime<ENCOUNTER_RHYTHM.pressureUntil&&d>135)return true;return false}
function encounterRhythmAwarenessScale(e){if(!G.started||!player||!e||e.boss||e.guardian||e.miniBossId||e.mini||e.eventId)return 1;let scale=1;if(onRoad(player.x,player.y,42)&&player.moving)scale*=BALANCE.rhythm.roadAwareness;if(G.playTime<ENCOUNTER_RHYTHM.respiteUntil)scale*=BALANCE.rhythm.respiteAwareness;if(G.playTime<ENCOUNTER_RHYTHM.pressureUntil)scale*=BALANCE.rhythm.pressureAwareness;if(encounterRhythmQuietStructureAt(player,0))scale*=.60;return clamp(scale,.42,1)}
function encounterRhythmRecordCombatStart(){const now=G.playTime||0;ENCOUNTER_RHYTHM.starts=ENCOUNTER_RHYTHM.starts.filter(t=>now-t<=BALANCE.rhythm.pressureWindow);ENCOUNTER_RHYTHM.starts.push(now);if(ENCOUNTER_RHYTHM.starts.length>=BALANCE.rhythm.pressureThreshold){const was=ENCOUNTER_RHYTHM.pressureUntil>now;ENCOUNTER_RHYTHM.pressureUntil=Math.max(ENCOUNTER_RHYTHM.pressureUntil,now+BALANCE.rhythm.pressureSeconds);if(!was){ENCOUNTER_RHYTHM.pressureTriggers++;PLAYTEST.rhythmPressureTriggers=(PLAYTEST.rhythmPressureTriggers||0)+1}}PLAYTEST.rhythmCombatStarts=(PLAYTEST.rhythmCombatStarts||0)+1}
function encounterRhythmPreTick(){if(!G.started||!player)return;const q=encounterRhythmQuietStructureAt(player,0),key=q?.structure?.id||'';if(key&&key!==ENCOUNTER_RHYTHM.lastQuietKey){ENCOUNTER_RHYTHM.quietEntries++;PLAYTEST.rhythmQuietEntries=(PLAYTEST.rhythmQuietEntries||0)+1}ENCOUNTER_RHYTHM.lastQuietKey=key}
function encounterRhythmPostTick(){if(!G.started||!player)return;const combat=player.combat>0;if(combat&&!ENCOUNTER_RHYTHM.wasCombat)encounterRhythmRecordCombatStart();if(!combat&&ENCOUNTER_RHYTHM.wasCombat){ENCOUNTER_RHYTHM.respiteUntil=Math.max(ENCOUNTER_RHYTHM.respiteUntil,G.playTime+BALANCE.rhythm.respiteSeconds);PLAYTEST.rhythmRespites=(PLAYTEST.rhythmRespites||0)+1}ENCOUNTER_RHYTHM.wasCombat=combat;ENCOUNTER_RHYTHM.starts=ENCOUNTER_RHYTHM.starts.filter(t=>G.playTime-t<=BALANCE.rhythm.pressureWindow)}
function encounterRhythmBlocksEvent(){if(!G.started||!player)return false;const blocked=!!encounterRhythmQuietStructureAt(player,70)||G.playTime<ENCOUNTER_RHYTHM.respiteUntil||G.playTime<ENCOUNTER_RHYTHM.pressureUntil;if(blocked){ENCOUNTER_RHYTHM.eventDeferrals++;PLAYTEST.rhythmEventDeferrals=(PLAYTEST.rhythmEventDeferrals||0)+1}return blocked}
function encounterRhythmHash(e,i){const n=Math.sin((e.homeX||e.x)*12.9898+(e.homeY||e.y)*78.233+i*37.719)*43758.5453;return n-Math.floor(n)}
function encounterRhythmRelocateEnemy(e,index){if(!e||e.dead||e.boss||e.guardian||e.miniBossId||e.mini||e.eventId||e.tideSpawn||e.noRespawn)return false;const q=encounterRhythmQuietStructureAt({x:e.homeX,y:e.homeY},65);if(!q)return false;const base=q.radius+78;for(let i=0;i<16;i++){const a=(i/16)*TAU+encounterRhythmHash(e,index)*TAU,r=base+(i%4)*28,x=q.structure.x+Math.cos(a)*r,y=q.structure.y+Math.sin(a)*r;if(!landAt(x,y,60)||!walkable(x,y,e.r)||encounterRhythmQuietStructureAt({x,y},40)||dist({x,y},HOME)<340||GUARDIANS.some(g=>dist({x,y},g)<190)||dist({x,y},BOSS_POS)<390)continue;e.x=e.homeX=x;e.y=e.homeY=y;e.aiState='idle';e.aggro=false;ENCOUNTER_RHYTHM.relocated++;PLAYTEST.rhythmRelocated=(PLAYTEST.rhythmRelocated||0)+1;return true}return false}
function encounterRhythmApplyWorldSpacing(){let n=0;for(let i=0;i<enemies.length;i++)if(encounterRhythmRelocateEnemy(enemies[i],i))n++;return n}
function encounterRhythmReport(){return {quietEntries:PLAYTEST.rhythmQuietEntries||0,combatStarts:PLAYTEST.rhythmCombatStarts||0,respites:PLAYTEST.rhythmRespites||0,pressureTriggers:PLAYTEST.rhythmPressureTriggers||0,eventDeferrals:PLAYTEST.rhythmEventDeferrals||0,nonCombatSwaps:PLAYTEST.rhythmNonCombatSwaps||0,relocated:PLAYTEST.rhythmRelocated||ENCOUNTER_RHYTHM.relocated,currentlyQuiet:!!encounterRhythmQuietStructureAt(player,0),respiteRemaining:+Math.max(0,ENCOUNTER_RHYTHM.respiteUntil-G.playTime).toFixed(1),pressureRemaining:+Math.max(0,ENCOUNTER_RHYTHM.pressureUntil-G.playTime).toFixed(1),recentCombats:ENCOUNTER_RHYTHM.starts.length,lastEventType:ENCOUNTER_RHYTHM.lastEventType}}

const _rhythmBaseResetPlaytest=resetPlaytest;
resetPlaytest=function(){_rhythmBaseResetPlaytest();Object.assign(PLAYTEST,{rhythmQuietEntries:0,rhythmCombatStarts:0,rhythmRespites:0,rhythmPressureTriggers:0,rhythmEventDeferrals:0,rhythmNonCombatSwaps:0,rhythmRelocated:0});encounterRhythmReset()};
const _rhythmBasePlaytestReport=playtestReport;
playtestReport=function(){const r=_rhythmBasePlaytestReport();r.encounterRhythm=encounterRhythmReport();return r};

const _rhythmBaseChooseDynamicEvent=chooseDynamicEvent;
chooseDynamicEvent=function(){const chosen=_rhythmBaseChooseDynamicEvent();if(!RHYTHM_COMBAT_EVENTS.has(chosen))return chosen;const now=G.playTime||0,highPressure=now<ENCOUNTER_RHYTHM.pressureUntil,recentCombatEvent=RHYTHM_COMBAT_EVENTS.has(ENCOUNTER_RHYTHM.lastEventType)&&now-ENCOUNTER_RHYTHM.lastEventAt<90;if(!highPressure&&!recentCombatEvent)return chosen;if(chosen==='countertide'&&!highPressure)return chosen;const r=eventRoll(G.eventSeq,1771),swap=r<.42?'birdFind':r<.76?'castaway':'merchant';ENCOUNTER_RHYTHM.nonCombatSwaps++;PLAYTEST.rhythmNonCombatSwaps=(PLAYTEST.rhythmNonCombatSwaps||0)+1;return swap};
const _rhythmBaseFinishDynamicEvent=finishDynamicEvent;
finishDynamicEvent=function(reason='complete'){const type=G.activeEvent?.type||'';_rhythmBaseFinishDynamicEvent(reason);if(!type)return;ENCOUNTER_RHYTHM.lastEventType=type;ENCOUNTER_RHYTHM.lastEventAt=G.playTime;if(RHYTHM_COMBAT_EVENTS.has(type)){ENCOUNTER_RHYTHM.respiteUntil=Math.max(ENCOUNTER_RHYTHM.respiteUntil,G.playTime+10);G.nextEventAt=Math.max(G.nextEventAt,G.playTime+EVENT_MIN_INTERVAL+12)}};

const _rhythmBaseBuildWorld=buildWorld;
buildWorld=function(){_rhythmBaseBuildWorld();encounterRhythmApplyWorldSpacing()};
const _rhythmBaseBuildWorldProgressiveMobile=buildWorldProgressiveMobile;
buildWorldProgressiveMobile=async function(){await _rhythmBaseBuildWorldProgressiveMobile();encounterRhythmApplyWorldSpacing()};

const _rhythmBaseUpdate=update;
update=function(dt){encounterRhythmPreTick();_rhythmBaseUpdate(dt);encounterRhythmPostTick()};

const _rhythmBaseRunSelfTest=runSelfTest;
runSelfTest=function(){const r=_rhythmBaseRunSelfTest(),f=[...(r.failures||[])];if(!Number.isFinite(BALANCE.rhythm.ambientEnemies)||BALANCE.rhythm.ambientEnemies<50)f.push('rhythm-ambient-count');if(G.started){const bad=enemies.filter(e=>!e.dead&&!e.boss&&!e.guardian&&!e.miniBossId&&!e.mini&&!e.eventId&&!e.noRespawn&&encounterRhythmQuietStructureAt({x:e.homeX,y:e.homeY},20));if(bad.length>2)f.push('rhythm-quiet-spawns:'+bad.length)}return {...r,ok:f.length===0,failures:f}};




