/* GD-028 — Final Player Experience Polish
   Pure UX/presentation layer. Save V7 is intentionally untouched. */
const FINAL_POLISH={
  version:1,
  lastRecapAt:-999,
  lastHealthHintAt:-999,
  lastSkillHintAt:-999,
  comboMilestone:0,
  previousCombat:0,
  previousOverlay:null,
  returningRecapShown:false,
  victorySummaryShown:false
};

function finalObjectiveLine(){
  if(!G?.started)return '';
  const target=questTarget?.();
  if(target)return `${target.name} · ${Math.max(0,Math.round(dist(player,target)/10))} m`;
  if(G.bossDefeated)return 'A ilha está livre · explore fios que ficaram abertos';
  if(G.seals?.length===3)return 'Recife Esquecido · enfrente Esponjão';
  return 'Recupere os três selos da ilha';
}

function finalShowObjectiveRecap(force=false){
  if(mobileRenderEnabled())return false;
  if(!G?.started||G.overlay||player?.combat>0||player?.hp<=0)return false;
  if(!force&&G.playTime-FINAL_POLISH.lastRecapAt<55)return false;
  const line=finalObjectiveLine();
  if(!line)return false;
  FINAL_POLISH.lastRecapAt=G.playTime;
  toast(`RUMO · ${line}`,'recap');
  return true;
}

function finalReturningRecap(){
  if(FINAL_POLISH.returningRecapShown||!G?.started||G.playTime<120)return;
  FINAL_POLISH.returningRecapShown=true;
  const zone=zoneAt(player.x,player.y);
  setTimeout(()=>{
    if(!G.started||G.overlay)return;
    toast(`DE VOLTA À MARÉ · Nv.${player.level} · ${G.seals.length}/3 selos · ${zone.name}`,'recap');
    setTimeout(()=>finalShowObjectiveRecap(true),1050);
  },950);
}

function finalCombatHeartbeat(){
  if(!G?.started||!player)return;
  const combat=player.combat||0;
  if(FINAL_POLISH.previousCombat>0&&combat<=0&&!G.overlay){
    const hpRatio=player.hp/Math.max(1,maxHP());
    if(hpRatio<.35&&player.potions>0&&G.playTime-FINAL_POLISH.lastHealthHintAt>90){
      FINAL_POLISH.lastHealthHintAt=G.playTime;
      setTimeout(()=>{if(G.started&&!G.overlay&&player.combat<=0)toast(`Você está ferido · ${player.potions} poção${player.potions===1?'':'ões'} disponível${player.potions===1?'':'is'}.`,'recap')},450);
    }else if(player.points>0&&G.playTime-FINAL_POLISH.lastSkillHintAt>180){
      FINAL_POLISH.lastSkillHintAt=G.playTime;
      setTimeout(()=>{if(G.started&&!G.overlay&&player.combat<=0)toast(`${player.points} ponto${player.points===1?'':'s'} de habilidade esperando uma decisão.`,'recap')},450);
    }
  }
  FINAL_POLISH.previousCombat=combat;

  const combo=player.comboStep||0;
  if(combo<1)FINAL_POLISH.comboMilestone=0;
  if(combo>=2&&FINAL_POLISH.comboMilestone<2){
    FINAL_POLISH.comboMilestone=2;
    text(player.x,player.y-70,'RITMO ×2','#ffe0a0',12);
  }
  if(combo>=3&&FINAL_POLISH.comboMilestone<3){
    FINAL_POLISH.comboMilestone=3;
    text(player.x,player.y-76,'MARÉ DE AÇO ×3','#fff0b7',13);
    if(typeof sound==='function')sound('perfect',.8);
  }
}

function finalInjectVictorySummary(){
  if(FINAL_POLISH.victorySummaryShown)return;
  const stats=document.querySelector('#modal .result-stats');
  if(!stats)return;
  FINAL_POLISH.victorySummaryShown=true;
  const box=document.createElement('div');
  box.className='final-run-summary';
  const mini=G.minibosses?.length||0,secrets=G.secrets?.length||0,deaths=G.deathCount||0,chests=G.chests?.length||0;
  box.innerHTML=`<span><b>${mini}</b> minibosses</span><span><b>${secrets}</b> segredos</span><span><b>${chests}</b> baús</span><span><b>${deaths}</b> quedas</span>`;
  stats.insertAdjacentElement('afterend',box);
}

// Keep the existing start behavior, then add a compact returning-player recap.
if(typeof finalizeGameStart==='function'){
  const _finalizeGameStart=finalizeGameStart;
  finalizeGameStart=function(data=null){
    const out=_finalizeGameStart(data);
    FINAL_POLISH.returningRecapShown=false;
    FINAL_POLISH.victorySummaryShown=false;
    FINAL_POLISH.previousCombat=0;
    FINAL_POLISH.comboMilestone=0;
    if(data)finalReturningRecap();
    return out;
  };
}

// When the player closes a navigation-heavy overlay, gently restore orientation.
if(typeof closeOverlay==='function'){
  const _closeOverlay=closeOverlay;
  closeOverlay=function(){
    const prev=G?.overlay;
    const out=_closeOverlay();
    if(G?.started&&['pause','map','quests','skills','equipment','achievements'].includes(prev)){
      setTimeout(()=>finalShowObjectiveRecap(false),360);
    }
    return out;
  };
}

// Preserve the existing victory screen and enrich it with run-memory stats.
if(typeof showVictory==='function'){
  const _showVictory=showVictory;
  showVictory=function(){
    FINAL_POLISH.victorySummaryShown=false;
    const out=_showVictory();
    finalInjectVictorySummary();
    return out;
  };
}

let finalPolishRaf=0;
function finalPolishTick(){
  try{finalCombatHeartbeat()}catch(_){/* presentation must never break gameplay */}
  finalPolishRaf=requestAnimationFrame(finalPolishTick);
}
// Heartbeat is driven by the main loop in this project.

function finalPolishSelfTest(){
  const failures=[];
  if(BUILD_ID!=='4.2-world5-gd028-final-player-experience')failures.push('build');
  if(CURRENT_SAVE_VERSION!==7)failures.push('save-version');
  if(typeof finalObjectiveLine!=='function')failures.push('objective-recap');
  if(typeof finalInjectVictorySummary!=='function')failures.push('victory-summary');
  if(!FINAL_POLISH||FINAL_POLISH.version!==1)failures.push('state');
  return {ok:failures.length===0,failures,version:FINAL_POLISH.version};
}



// ---- beta/06j-story-runtime.js ----
'use strict';
// Runtime pequeno sobre os eventos existentes; pending permanece no save até a cena fechar.
const STORY_SCENE_IDS=Object.keys(STORY_DEFS.scenes),STORY_ENTRY_IDS=[...new Set([...Object.values(STORY_DEFS.scenes).map(s=>s.entry?.id).filter(Boolean),...Object.keys(STORY_DEFS.journalEntries)])];
function storyDefaultState(){return {version:1,seen:{},journal:{unlocked:[]},counters:{sealsObserved:0,ancientMarksObserved:0,mechanismsObserved:0},pending:[],marks:[],mechanisms:[],flags:{},values:{}}}
function storySealState(seals=G.seals){const ids=['moss','mire','bronze'].filter(id=>seals.includes(id));return {count:ids.length,scenes:ids.map(id=>'story.seal.'+(id==='mire'?'mud':id))}}
function storyCleanState(raw){const d=storyDefaultState();if(!raw||typeof raw!=='object')return d;d.seen=Object.fromEntries(Object.entries(raw.seen||{}).filter(([k,v])=>STORY_SCENE_IDS.includes(k)&&v===true));d.journal.unlocked=[...new Set((Array.isArray(raw.journal?.unlocked)?raw.journal.unlocked:[]).filter(id=>STORY_ENTRY_IDS.includes(id)))];for(const k of Object.keys(d.counters))d.counters[k]=Math.floor(clamp(Number(raw.counters?.[k])||0,0,5));d.pending=[...new Set((Array.isArray(raw.pending)?raw.pending:[]).filter(id=>STORY_SCENE_IDS.includes(id)&&!d.seen[id]))].sort((a,b)=>(STORY_DEFS.scenes[b]?.priority||0)-(STORY_DEFS.scenes[a]?.priority||0));d.marks=[...new Set((Array.isArray(raw.marks)?raw.marks:[]).filter(id=>typeof LIVING_MYSTERY_IDS!=='undefined'&&LIVING_MYSTERY_IDS.includes(id)))];d.mechanisms=[...new Set((Array.isArray(raw.mechanisms)?raw.mechanisms:[]).filter(id=>typeof V3_SITE_ENTRIES!=='undefined'&&V3_SITE_ENTRIES.some(([k])=>k===id)))];d.counters.ancientMarksObserved=d.marks.length;d.counters.mechanismsObserved=d.mechanisms.length;d.flags=Object.fromEntries(Object.entries(raw.flags||{}).filter(([k,v])=>STORY_SCENE_IDS.includes(k)&&typeof v==='boolean'));d.values=Object.fromEntries(Object.entries(raw.values||{}).filter(([k,v])=>['bossPhase'].includes(k)&&Number.isFinite(v)).map(([k,v])=>[k,clamp(Math.floor(v),0,3)]));return d}
function storyState(){if(!G.exploration)G.exploration={known:[],solved:[]};if(!G.exploration.storyBeats){const s=storyDefaultState();s.marks=[...(G.exploration.mystery||[])].filter(id=>typeof LIVING_MYSTERY_IDS!=='undefined'&&LIVING_MYSTERY_IDS.includes(id));s.mechanisms=[...(G.exploration.solved||[])].filter(id=>typeof V3_SITES!=='undefined'&&v3Own(V3_SITES,id));s.counters.sealsObserved=G.seals?.length||0;s.counters.ancientMarksObserved=s.marks.length;s.counters.mechanismsObserved=s.mechanisms.length;if(G.tutorial?.mara){s.seen['story.arrival.mara']=true;s.journal.unlocked.push('journal.arrival')}G.exploration.storyBeats=s}return G.exploration.storyBeats}
function storySafe(){return !!(G.started&&player?.hp>0&&!G.overlay&&player.combat<=0&&!enemies.some(e=>!e.dead&&e.aggro&&dist(e,player)<250))}
function storySave(){if(G.started&&player?.hp>0)saveGame()}
function storyAddJournal(id){const s=storyState();if(STORY_ENTRY_IDS.includes(id)&&!s.journal.unlocked.includes(id))s.journal.unlocked.push(id)}
function storyEffect(effect){const s=storyState();switch(effect?.type){case'setStoryFlag':if(STORY_SCENE_IDS.includes(effect.flag))s.flags[effect.flag]=true;break;case'setStoryValue':if(effect.key==='bossPhase')s.values.bossPhase=clamp(Math.floor(Number(effect.value)||0),0,3);break;case'addJournalEntry':storyAddJournal(effect.id);break;case'updateJournalEntry':storyAddJournal(effect.id);break;case'showToast':toast(String(effect.text||'').slice(0,120),'gold');break;case'updateMainObjective':updateHUD();break;case'unlockStoryHint':storyAddJournal(effect.id);break;case'playExistingSound':sound(effect.id||'quest',.7);break;case'focusExistingWorldObject':if(effect.id)toast('Novo ponto de interesse registrado no mapa.');break;case'requestAutosave':storySave();break;default:break}}
function storyQueue(id){const d=STORY_DEFS.scenes[id],s=storyState();if(!d||s.seen[id]||s.pending.includes(id))return false;s.pending.push(id);s.pending.sort((a,b)=>(STORY_DEFS.scenes[b]?.priority||0)-(STORY_DEFS.scenes[a]?.priority||0));storySave();storyTick();return true}
let STORY_PLAYING=null;
function storyRender(){const id=STORY_PLAYING,s=storyState(),d=STORY_DEFS.scenes[id];if(!d)return;const i=s.values['node:'+id]||0,[speaker,line]=d.nodes[i]||['', ''];const label=speaker==='Esponjão'?'Esponjão':speaker,content=modalHeader('A ILHA QUE LEMBRA',d.title)+`<div class="dialogue" aria-live="polite">${label?`<b>${label}</b><br>`:''}${line}</div><div class="modal-actions"><button id="story-next" class="primary" style="width:100%">${i<d.nodes.length-1?'Continuar':'Fechar'}</button></div><div class="footer-note">${i+1} / ${d.nodes.length}</div>`;setModal('story',content,true);$('close-modal').onclick=()=>storyFinish(id);const next=$('story-next');next.onclick=()=>{if(i<d.nodes.length-1){s.values['node:'+id]=i+1;storyRender()}else storyFinish(id)}}
function storyFinish(id){const s=storyState(),d=STORY_DEFS.scenes[id];if(!d)return;delete s.values['node:'+id];s.seen[id]=true;s.pending=s.pending.filter(v=>v!==id);if(d.entry)storyAddJournal(d.entry.id);for(const effect of d.effects||[])storyEffect(effect);if(id==='story.arrival.mara'){G.tutorial.mara=true;questEvent('talk',{npc:'mara'})}if(id==='story.seal.moss'||id==='story.seal.mud'||id==='story.seal.bronze'){const n=storySealState().count;if(n===1)storyQueue('story.progress.firstSeal');if(n===2){storyQueue('story.progress.twoSeals');storyQueue('story.esponjao.firstVoice')}if(n===3){storyQueue('story.progress.threeSeals');storyQueue('story.mara.beforeFinal')}}if(id==='story.boss.defeated'){if(typeof POLISH!=='undefined')POLISH.tidePulse=1.8;setTimeout(()=>{if(G.started&&G.bossDefeated)toast('As marés voltaram a correr.','gold')},1500)}STORY_PLAYING=null;storySave();closeOverlay();updateHUD();storyTick()}
function storyTick(){if(STORY_PLAYING||!storySafe())return;const s=storyState();if(s.marks.length===5&&!s.seen['story.marks.complete']&&!s.pending.includes('story.marks.complete'))s.pending.push('story.marks.complete');if(s.mechanisms.length===5&&!s.seen['story.mechanisms.complete']&&!s.pending.includes('story.mechanisms.complete'))s.pending.push('story.mechanisms.complete');s.pending.sort((a,b)=>(STORY_DEFS.scenes[b]?.priority||0)-(STORY_DEFS.scenes[a]?.priority||0));const id=s.pending[0];if(!id)return;if(s.seen[id]){s.pending.shift();storySave();return storyTick()}STORY_PLAYING=id;const d=STORY_DEFS.scenes[id];if(id.startsWith('story.region.')||d.toastOnly){s.seen[id]=true;s.pending.shift();if(d.entry)storyAddJournal(d.entry.id);const line=d.nodes[0]?.[1];if(line)toast(line);storySave();STORY_PLAYING=null;return storyTick()}storyRender()}
function storyNotify(type,data={}){const s=storyState();if(type==='maraInteraction'&&!G.bossDefeated)storyQueue('story.arrival.mara');if(type==='regionEnter'){const key={meadow:'fields',forest:'forest',marsh:'swamp',dunes:'dunes',reef:'reef'}[data.id];if(key)storyQueue('story.region.'+key);if(data.id==='reef'&&G.seals.length===3)storyQueue('story.reef.approach');if(data.id==='meadow'&&G.bossDefeated&&dist(player,HOME)<240)storyQueue('story.epilogue.basic')}
 if(type==='sealCollected'){const id={moss:'moss',mire:'mud',bronze:'bronze'}[data.id];if(id){const count=storySealState().count;s.counters.sealsObserved=count;sound('secret',.55);if(typeof POLISH!=='undefined')POLISH.tidePulse=.8;if(!reducedMotion())G.shake=Math.max(G.shake,1.8);if(bird)bird.celebrate=.7;storyQueue('story.seal.'+id);if(count===3){storyAddJournal('journal.lastTide');if(typeof POLISH!=='undefined')POLISH.tidePulse=1.6}}}
 if(type==='markFound'&&data.id&&!s.marks.includes(data.id)){s.marks.push(data.id);s.counters.ancientMarksObserved=s.marks.length;if(s.marks.length===1)storyAddJournal('journal.mark1');if(s.marks.length===2)storyAddJournal('journal.mark2');if(s.marks.length===3)storyQueue('story.marks.third');if(s.marks.length===4)storyAddJournal('journal.mark4');if(s.marks.length===5)storyQueue('story.marks.complete');if(lowTideOpen())storyQueue('story.weather.lowTideMark')}
 if(type==='mechanismSolved'&&data.id&&!s.mechanisms.includes(data.id)){s.mechanisms.push(data.id);s.counters.mechanismsObserved=s.mechanisms.length;const n=s.mechanisms.length;if(n<5)storyAddJournal('journal.mechanism'+n);const at=['','story.mechanisms.first','story.mechanisms.second','story.mechanisms.third','story.mechanisms.fourth','story.mechanisms.complete'][n];if(at)storyQueue(at)}
 if(type==='bossIntro')storyQueue('story.boss.intro');if(type==='bossDefeated')storyQueue('story.boss.defeated');storyTick()}
function storyJournalHTML(){const s=storyState(),entries=STORY_ENTRY_IDS.filter(id=>s.journal.unlocked.includes(id));if(!entries.length)return '';return `<section class="v3-journal"><div class="eyebrow">ILHA · DIÁRIO DE NILO</div>`+entries.map(id=>{const e=STORY_DEFS.journalEntries[id]||Object.values(STORY_DEFS.scenes).find(v=>v.entry?.id===id)?.entry;return e?`<article class="v3-biome-notes"><b>${e.title}</b><p>${e.text.replaceAll('\n','<br>')}</p></article>`:''}).join('')+'</section>'}

// Reuse os pontos de entrada existentes para manter o fluxo de jogo e Save V7.
const _storyInteract=interact;interact=function(){if(nearby?.kind==='camp'&&!G.bossDefeated){if(!storyState().seen['story.arrival.mara'])storyNotify('maraInteraction');else if(G.seals.length===3&&!storyState().seen['story.mara.beforeFinal'])storyQueue('story.mara.beforeFinal');else if(storyState().marks.length===5&&!storyState().seen['story.marks.safePoint'])storyQueue('story.marks.safePoint');if(STORY_PLAYING||!storySafe())return}_storyInteract()};
const _storyUpdateHUD=updateHUD;updateHUD=function(){_storyUpdateHUD();if(G.started){if(lastZone)storyNotify('regionEnter',{id:lastZone});const s=storyState(),title=$('quest-title'),desc=$('quest-desc');if(!G.tutorial.mara){title.textContent='Explore o Abrigo.';desc.textContent='Converse com Mara ao lado da fogueira.'}else if(G.bossDefeated){if(s.seen['story.epilogue.basic']){title.textContent='Maré livre';desc.textContent='A ilha continua mudando. Explore no seu ritmo.'}else{title.textContent='Volte ao Abrigo';desc.textContent='Conte a Mara que as marés voltaram.'}}else if(G.seals.length===3){title.textContent='Vá ao Recife Esquecido';desc.textContent='Os três selos abriram o caminho — e despertaram alguma coisa.'}else if(G.seals.length===2){title.textContent='Recupere o último selo';desc.textContent='O Recife está reagindo. 2/3'}else{title.textContent='Recupere os três selos';desc.textContent=G.seals.length+' / 3 · Os guardiões podem ser enfrentados em qualquer ordem.'}if(G.seals.length>=2&&weatherNow().id==='storm')storyQueue('story.weather.storm');if(lastZone==='reef'&&weatherNow().id==='fog')storyQueue('story.weather.fogReef');if(G.bossDefeated&&dist(player,HOME)<180){storyQueue('story.epilogue.basic');if(s.marks.length===5)storyQueue('story.epilogue.marks');if(s.mechanisms.length===5)storyQueue('story.epilogue.mechanisms');if(Object.values(G.quests||{}).filter(q=>q.status==='done').length>=5&&s.marks.length===5&&s.mechanisms.length===5)storyQueue('story.epilogue.community')}storyTick()}};
const _storyCloseOverlay=closeOverlay;closeOverlay=function(){_storyCloseOverlay();STORY_PLAYING=null;storyTick()};
const _storyShowQuestLog=showQuestLog;showQuestLog=function(){_storyShowQuestLog();$('modal').insertAdjacentHTML('beforeend',storyJournalHTML());v3BindJournal()};
