const _storyMaraLine=livingMaraLine;livingMaraLine=function(){if(G.seals.length===1&&storyState().seen['story.progress.firstSeal'])return 'Um já mexeu com a ilha. Isso é bom ou ruim? Quando eu souber, você vai ser o segundo.';if(G.seals.length===2&&storyState().seen['story.progress.twoSeals'])return 'Antes, o mar estava errado. Agora ele está irritado.';return _storyMaraLine()};
const _storyCollectLoot=collectLoot;collectLoot=function(l){const was=l?.type==='seal'&&!G.seals.includes(l.id);_storyCollectLoot(l);if(was&&G.seals.includes(l.id))storyNotify('sealCollected',{id:l.id})};
const _storyMark=livingDiscoverMystery;livingDiscoverMystery=function(id){const before=livingState().mystery.includes(id),r=_storyMark(id);if(!before&&livingState().mystery.includes(id))storyNotify('markFound',{id});return r};
