const _storyBossSpeak=bossSpeak;bossSpeak=function(e,line){if(e?.boss&&!e._storyIntro){e._storyIntro=true;if(!ngActive()){storyNotify('bossIntro');return}}if(e?.boss&&e.phaseNo===1&&e.hp/e.maxHp<.86&&!e._storyMossBark){e._storyMossBark=true;line='Raiz boa não solta.'}if(e?.boss&&e.phaseNo===2)line='A maré sobe.';if(e?.boss&&e.phaseNo===3)line='Agora a ilha afunda com vocês.';return _storyBossSpeak(e,line)};
const _storyUpdateBoss=updateBoss;updateBoss=function(e,dt){const r=_storyUpdateBoss(e,dt);if(e?.boss&&e.awake&&e.phaseNo===1&&e.hp/e.maxHp<.86&&!e._storyMossBark)bossSpeak(e,'Raiz boa não solta.');return r};
const _storyNGStart=startNewGamePlus;startNewGamePlus=function(){const out=_storyNGStart();if(out){const c=ngCycle(),key=c===1?'iron':c===2?'wake':c===3?'short':'route',d=STORY_DEFS.countertideIntros[key];setTimeout(()=>{if(G.started&&ngActive()){toast(d.title,'gold');setTimeout(()=>{if(G.started&&ngActive())toast(d.text)},1900)}},1800)}return out};
const _storyKillEnemy=killEnemy;killEnemy=function(e){const boss=e?.boss&&!e.dead;_storyKillEnemy(e);if(boss&&G.bossDefeated)storyNotify('bossDefeated')};
const _storyShowVictory=showVictory;showVictory=function(){if(STORY_PLAYING||storyState().pending.length){setTimeout(()=>{if(G.started&&G.bossDefeated)showVictory()},500);return}return _storyShowVictory()};
function storySelfTest(){const perms=[['moss','mire','bronze'],['moss','bronze','mire'],['mire','moss','bronze'],['mire','bronze','moss'],['bronze','moss','mire'],['bronze','mire','moss']],resume=storyCleanState({pending:['story.arrival.mara','invalid'],seen:{'story.region.forest':true}});return perms.every(order=>new Set(order).size===3&&storySealState(order).count===3&&storySealState(order).scenes.length===3&&order.every(id=>STORY_DEFS.scenes['story.seal.'+(id==='mire'?'mud':id)]))&&STORY_SCENE_IDS.includes('story.progress.threeSeals')&&STORY_ENTRY_IDS.includes('journal.arrival')&&resume.pending.length===1&&resume.pending[0]==='story.arrival.mara'?[]:['story-permutation-or-content']}



