// Presentation only; combat calculations remain in 02b-combat-rules.js.
function rpgStatText(stats){const labels={hp:'vida',stamina:'energia',damage:'espada',hook:'gancho',bird:'Pipoca',crit:'crítico',posture:'postura',counter:'contra-ataque'};return Object.entries(stats).map(([k,v])=>'+'+(v<1?Math.round(v*100)+'%':v)+' '+labels[k]).join(' · ')}
function rpgItemComparison(id){const d=EQUIPMENT_DEFS[id],old=G.equipment[d.slot],a=RPG_ITEMS[id]?.stats||{},b=RPG_ITEMS[old]?.stats||{},keys=new Set([...Object.keys(a),...Object.keys(b)]);return [...keys].map(k=>{const v=(a[k]||0)-(b[k]||0);return (v>=0?'+':'')+(Math.abs(v)<1&&v!==0?Math.round(v*100)+'%':v)+' '+({hp:'vida',stamina:'energia',damage:'espada',hook:'gancho',bird:'Pipoca',crit:'crítico',posture:'postura',counter:'contra-ataque'}[k])}).join(' · ')||'Mesmo valor de atributos'}
